import type { Question } from '../types'

export const vquestions: Question[] = [
  // ═══ MODULE 1 — Histoire des systèmes distribués ═══
  { id: 'vq101', module: 'v1', q: 'Au tout début de l\u2019informatique, un ordinateur pouvait effectuer…', options: ['Plusieurs tâches simultanément', 'Une seule tâche à la fois', 'Uniquement des calculs mathématiques', 'Des tâches réparties sur un réseau'], answer: 1, explain: 'Au tout début, un ordinateur ne pouvait effectuer qu\u2019une seule tâche à la fois ; pour plusieurs tâches en parallèle, il fallait plusieurs ordinateurs en parallèle.' },
  { id: 'vq102', module: 'v1', q: 'Pourquoi le parallélisme seul ne suffit-il pas à construire un système distribué ?', options: ['Il faut des ordinateurs plus puissants', 'Il faut un mécanisme pour communiquer entre les ordinateurs (ou leurs programmes)', 'Il faut des OS multitâches', 'Il faut Internet'], answer: 1, explain: 'Il nécessite un mécanisme pour communiquer entre différents ordinateurs (ou programmes exécutés sur ces ordinateurs).' },
  { id: 'vq103', module: 'v1', q: 'Comment deux ordinateurs partagent-ils des données dans la communication orientée message ?', options: ['Via un disque partagé uniquement', 'À l\u2019aide d\u2019un message qui encapsule les données', 'Par clonage de fichiers', 'Par multi-boot'], answer: 1, explain: 'Deux ordinateurs partagent des données à l\u2019aide d\u2019un message qui les encapsule (communication orientée message).' },
  { id: 'vq104', module: 'v1', q: 'Quels autres mécanismes de partage existaient en plus des messages ?', options: ['Le partage de fichiers et le partage de base de données', 'Le cloud et les conteneurs', 'RAID et SAN', 'SSH et FTP'], answer: 0, explain: 'Il y avait peu d\u2019autres mécanismes : le partage de fichiers et le partage de base de données.' },
  { id: 'vq105', module: 'v1', q: 'Quelle invention a permis de créer et d\u2019exécuter des systèmes distribués complets ?', options: ['Les OS multitâches (Windows, Unix)', 'Les disques SSD', 'Les routeurs', 'Les API REST'], answer: 0, explain: 'L\u2019invention des OS multitâches, tels que Windows et Unix, a permis aux développeurs de créer et d\u2019exécuter des systèmes distribués complets.' },
  { id: 'vq106', module: 'v1', q: 'Dans SOA, comment les interfaces de service sont-elles définies ?', options: ['WSDL (pour SOAP) ou WADL (pour REST)', 'HTML et CSS', 'JSON uniquement', 'SQL'], answer: 0, explain: 'Les interfaces de service ont été correctement définies via un WSDL (pour SOAP) ou un WADL (pour REST).' },
  { id: 'vq107', module: 'v1', q: 'Pourquoi REST est-elle devenue plus populaire que SOAP ?', options: ['Elle est plus ancienne', 'Avec la popularité d\u2019Internet et la simplicité du modèle', 'Elle est payante', 'Elle ne nécessite pas de réseau'], answer: 1, explain: 'Avec la popularité d\u2019Internet et la simplicité du modèle, la communication basée sur REST est devenue plus populaire que SOAP.' },
  { id: 'vq108', module: 'v1', q: 'Comment le cours représente-t-il une API ?', options: ['Un serveur de fichiers', 'Un médiateur entre les utilisateurs/clients et les ressources ou services web', 'Un langage de programmation', 'Une base de données'], answer: 1, explain: 'On peut se représenter une API comme un médiateur entre les utilisateurs (ou clients) et les ressources ou services web auxquels ils souhaitent accéder.' },
  { id: 'vq109', module: 'v1', q: 'Pour les entreprises, l\u2019API est aussi une solution pour…', options: ['Supprimer la sécurité', 'Partager des ressources et informations tout en maintenant un certain niveau de sécurité', 'Remplacer les serveurs', 'Écrire des OS'], answer: 1, explain: 'Pour une entreprise, l\u2019API est une solution pour partager des ressources et des informations tout en maintenant un certain niveau de sécurité.' },
  { id: 'vq110', module: 'v1', q: 'Quelles entreprises ont poussé le développement des systèmes distribués multi-zones ?', options: ['IBM et Dell', 'Facebook, Google, Amazon, Netflix, LinkedIn, Twitter', 'Uniquement des universités', 'Les opérateurs téléphoniques'], answer: 1, explain: 'L\u2019importance des entreprises basées sur Internet telles que Facebook, Google, Amazon, Netflix, LinkedIn et Twitter : elles voulaient des systèmes distribués couvrant plusieurs zones géographiques et centres de données.' },
  { id: 'vq111', module: 'v1', q: 'Quelle technologie rend possible le cloud computing ?', options: ['RAID', 'La virtualisation', 'La fibre optique', 'Le multi-boot'], answer: 1, explain: 'La technologie de virtualisation rend possible le cloud computing.' },
  { id: 'vq112', module: 'v1', q: 'Comment accède-t-on aux ressources en cloud ?', options: ['En branchant un câble', 'À l\u2019aide des APIs', 'Par disque externe', 'Via le BIOS'], answer: 1, explain: 'Vous programmez votre système pour qu\u2019il accède à ces ressources en cloud à l\u2019aide des APIs. Les fournisseurs créent des environnements virtuels sur leurs datacenters.' },

  // ═══ MODULE 2 — Ordinateur & serveurs ═══
  { id: 'vq201', module: 'v2', q: 'Que stocke la ROM ?', options: ['Les données en cours d\u2019utilisation', 'Un logiciel appelé BIOS', 'Les programmes utilisateur', 'Le cache du CPU'], answer: 1, explain: 'La ROM (Read Only Memory) est une mémoire non volatile qui stocke un logiciel appelé BIOS, responsable du démarrage du matériel.' },
  { id: 'vq202', module: 'v2', q: 'Que contient la carte mère ?', options: ['Uniquement le CPU', 'PCB contenant processeur, RAM, ROM, réseau et ports I/O', 'Uniquement la RAM', 'Le système d\u2019exploitation'], answer: 1, explain: 'Carte mère = PCB (Printed Circuit Board) contenant le processeur, la RAM, la ROM, le réseau et les ports I/O, ainsi que d\u2019autres composants.' },
  { id: 'vq203', module: 'v2', q: 'Que contient la RAM ?', options: ['Le BIOS', 'Les programmes à exécuter et les données actuellement utilisées par le processeur', 'Le système de fichiers permanent', 'Les pilotes d\u2019impression'], answer: 1, explain: 'La RAM (Random Access Memory) contient les programmes à exécuter et les données actuellement utilisées par le processeur.' },
  { id: 'vq204', module: 'v2', q: 'Le logiciel système est écrit en…', options: ['Langage évolué (Java, C++, .net, VB)', 'Langage de bas niveau (assemblage)', 'Python uniquement', 'HTML'], answer: 1, explain: 'Le logiciel système est écrit dans un langage de bas niveau (langage d\u2019assemblage) ; le logiciel d\u2019application dans un langage évolué (Java, C++, .net, VB…).' },
  { id: 'vq205', module: 'v2', q: 'Quel logiciel est INDISPENSABLE au fonctionnement du système ?', options: ['Le logiciel d\u2019application', 'Le logiciel système', 'Microsoft Office', 'Photoshop'], answer: 1, explain: 'Un système ne peut pas fonctionner sans logiciel système ; le logiciel d\u2019application n\u2019est même pas nécessaire pour exécuter le système (spécifique à l\u2019utilisateur).' },
  { id: 'vq206', module: 'v2', q: 'Un serveur physique est mis à disposition de…', options: ['Plusieurs entreprises anonymes', 'Un seul client (ex. les membres d\u2019une entreprise)', 'Tout Internet', 'Uniquement des VM'], answer: 1, explain: 'Le serveur physique est mis à disposition d\u2019un seul client (ex. accessible que par les membres d\u2019une entreprise).' },
  { id: 'vq207', module: 'v2', q: 'Quel serveur filtre les communications et contrôle la bande passante ?', options: ['Serveur Web', 'Serveur Proxy', 'Serveur d\u2019impression', 'Serveur email'], answer: 1, explain: 'Le serveur Proxy sert d\u2019interface de communication dans des réseaux d\u2019ordinateurs pour filtrer les communications et contrôler la bande passante.' },
  { id: 'vq208', module: 'v2', q: 'Quel serveur permet à plusieurs ordinateurs d\u2019imprimer à distance ?', options: ['Serveur de fichiers', 'Serveur d\u2019impression', 'Serveur Proxy', 'Serveur Web'], answer: 1, explain: 'Serveur d\u2019impression : plusieurs ordinateurs peuvent être connectés à distance pour imprimer des fichiers.' },
  { id: 'vq209', module: 'v2', q: 'Quel format de serveur peut être installé dans n\u2019importe quelle pièce, sans baie ?', options: ['Rack', 'Lame (blade)', 'Tour', 'Tous'], answer: 2, explain: 'Le format tour ressemble à une unité centrale fixe et peut être installé dans n\u2019importe quelle pièce ; rack et lame nécessitent une baie.' },
  { id: 'vq210', module: 'v2', q: 'Comment sont installés les serveurs au format lame (blade) ?', options: ['Posés au sol', 'Glissés verticalement dans un casier dédié', 'Encastrés dans un mur', 'Sur un bureau'], answer: 1, explain: 'Compact et mince comme une lame, le serveur lame se glisse verticalement dans un casier dédié.' },
  { id: 'vq211', module: 'v2', q: 'Sur quoi fonctionne un serveur virtuel ?', options: ['Directement sur le matériel', 'Sur un logiciel spécialisé appelé hyperviseur', 'Sur un NAS', 'Sur le cloud uniquement'], answer: 1, explain: 'Le serveur virtuel ne fonctionne pas sur un ordinateur physique mais sur un logiciel spécialisé, également appelé hyperviseur.' },
  { id: 'vq212', module: 'v2', q: 'Un serveur virtuel peut-il avoir son propre OS ?', options: ['Non, il partage le BIOS', 'Oui, en utilisant des techniques de virtualisation', 'Uniquement sous Windows', 'Seulement s\u2019il est en rack'], answer: 1, explain: 'Le serveur virtuel est capable d\u2019exécuter son propre OS en utilisant des techniques de virtualisation, et peut être migré facilement vers le cloud.' },

  // ═══ MODULE 3 — Virtualisation : concepts ═══
  { id: 'vq301', module: 'v3', q: 'Quelle part des serveurs des datacenters ont une utilisation moyenne inférieure à 10 % ?', options: ['30 %', '50 %', '80 %', '95 %'], answer: 2, explain: '80 % des serveurs ont une utilisation moyenne inférieure à 10 % — un argument majeur de la virtualisation.' },
  { id: 'vq302', module: 'v3', q: 'Que recommandent les éditeurs (Microsoft, distributions Linux) ?', options: ['Plusieurs applications par OS', 'Une application/service par système d\u2019exploitation', 'Pas d\u2019OS du tout', 'Un OS par application métier'], answer: 1, explain: 'Les éditeurs recommandent une application/service par système d\u2019exploitation : un serveur DNS, un serveur mail, un serveur NFS, etc.' },
  { id: 'vq303', module: 'v3', q: 'La virtualisation est-elle du multi-boot ?', options: ['Oui, exactement', 'Non, ce n\u2019est pas du multi-boot', 'Seulement sous Linux', 'Seulement avec LVM'], answer: 1, explain: 'Le cours précise : « C\u2019est pas du multi-boot ». La virtualisation fait tourner plusieurs OS SIMULTANÉMENT sur une même machine.' },
  { id: 'vq304', module: 'v3', q: 'Comment appelle-t-on un environnement exploitant la virtualisation ?', options: ['VE (Virtual Environment) ou VPS (Virtual Private Server)', 'LAN ou WAN', 'DNS ou DHCP', 'RAID'], answer: 0, explain: 'On parle d\u2019environnement virtuel (VE) ou de serveur privé virtuel (VPS) lorsqu\u2019une machine exploite la virtualisation.' },
  { id: 'vq305', module: 'v3', q: 'Quel est le rôle de l\u2019hyperviseur vis-à-vis des ressources physiques ?', options: ['Les afficher à l\u2019utilisateur', 'Les masquer et proposer des ressources spécifiques aux applications', 'Les doubler', 'Les formater'], answer: 1, explain: 'L\u2019hyperviseur masque les véritables ressources physiques et propose des ressources différentes et spécifiques selon les applications (nouvelle configuration) → indépendance matériel/applications.' },
  { id: 'vq306', module: 'v3', q: 'Le cloisonnement signifie que…', options: ['Chaque OS a un fonctionnement indépendant et ne peut interférer avec les autres', 'Les OS partagent tout', 'L\u2019OS hôte contrôle les invités en tout', 'Les VMs sont chiffrées'], answer: 0, explain: 'Cloisonnement : chaque système d\u2019exploitation a un fonctionnement indépendant et ne peut interférer avec les autres en aucune manière.' },
  { id: 'vq307', module: 'v3', q: 'La transparence implique…', options: ['La gratuité', 'La compatibilité : toutes les applications peuvent tourner sans modification', 'Le chiffrement', 'La mise en cluster'], answer: 1, explain: 'La transparence implique la compatibilité : toutes les applications peuvent tourner sur un système virtualisé et leur fonctionnement n\u2019est en rien modifié.' },
  { id: 'vq308', module: 'v3', q: 'Parmi les cas d\u2019utilisation de la virtualisation :', options: ['Tester un OS sans l\u2019installer, tester la compatibilité d\u2019une application, créer un petit réseau…', 'Augmenter la RAM physique', 'Remplacer le disque dur', 'Accélérer Internet'], answer: 0, explain: 'Cas d\u2019usage : tester un OS sans l\u2019installer, compatibilité d\u2019une application avec différents OS, environnement particulier, simuler une 2e machine, petit réseau, multi-OS, partage de serveur, HA, migration, maintenance.' },
  { id: 'vq309', module: 'v3', q: 'Quel est un INCONVÉNIENT de la virtualisation ?', options: ['Plus de serveurs physiques nécessaires', 'Machine physique en panne → suspension de tous les services', 'Impossible de faire du monitoring', 'Pas de portabilité'], answer: 1, explain: 'Inconvénients : plusieurs VE sur une unique machine physique ; panne physique = suspension de tous les services ; machines puissantes requises ; outils gourmands ; possible perte de performances.' },
  { id: 'vq310', module: 'v3', q: 'Quels sont les DEUX éléments constituant une machine virtuelle ?', options: ['BIOS et firmware', 'Ressources (CPU, RAM, cartes réseau virtuelles) et données (OS, bibliothèques, outils, applications, données)', 'Kernel et shell', 'Cache et registres'], answer: 1, explain: 'Une VM se compose de deux éléments : ressources (part de CPU allouée, mémoire vive autorisée, cartes réseau virtuelles) et données (OS, bibliothèques, outils, applications et leurs données).' },
  { id: 'vq311', module: 'v3', q: 'À quoi sert le fichier <vmname>.vmx ?', options: ['Journal d\u2019activité', 'Configuration : nom de la VM, BIOS, OS invité, taille mémoire', 'Disque virtuel', 'Snapshot'], answer: 1, explain: '<vmname>.vmx (Configuration file) stocke le nom de la VM, les informations BIOS, le type d\u2019OS invité et la taille de la mémoire.' },
  { id: 'vq312', module: 'v3', q: 'Que stocke <vmname>.vmdk ?', options: ['L\u2019état du BIOS', 'Le contenu de l\u2019unité de disque de la VM (un ou plusieurs fichiers selon la taille)', 'Le journal de logs', 'La configuration mémoire'], answer: 1, explain: '<vmname>.vmdk (Virtual disk file) stocke le contenu de l\u2019unité de disque ; un disque virtuel peut être composé de plusieurs fichiers .vmdk.' },
  { id: 'vq313', module: 'v3', q: 'Un snapshot…', options: ['Crée une copie complète du disque', 'Stocke uniquement les changements depuis le snapshot ; rapide mais ne remplace pas une sauvegarde complète', 'Supprime la VM', 'Clone le réseau'], answer: 1, explain: 'Le snapshot ne crée pas une copie complète du disque, il stocke les changements depuis le snapshot ; rapide à créer/restaurer mais ne remplace pas une sauvegarde complète.' },
  { id: 'vq314', module: 'v3', q: 'Quelle est l\u2019utilité d\u2019un snapshot ?', options: ['Revenir rapidement à un état précédent en cas d\u2019erreur ou de test ; sauvegarder avant une mise à jour critique', 'Augmenter les performances', 'Migrer vers le cloud', 'Changer d\u2019hyperviseur'], answer: 0, explain: 'Utilités du snapshot : revenir rapidement à un état précédent (erreur/test) et sauvegarder la configuration avant une mise à jour ou modification critique.' },
  { id: 'vq315', module: 'v3', q: 'Quelle est la différence entre clone lié et clone complet ?', options: ['Le clone lié dépend de l\u2019original (économise l\u2019espace), le clone complet est totalement indépendant', 'Aucune différence', 'Le clone complet nécessite la VM source', 'Le clone lié est plus rapide à créer mais plus volumineux'], answer: 0, explain: 'Clonage complet : copie totale indépendante. Clonage lié : dépend de l\u2019original, économise de l\u2019espace mais nécessite la VM source.' },
  { id: 'vq316', module: 'v3', q: 'Quels fichiers contient un export au format OVF ?', options: ['Un seul fichier exécutable', 'La configuration (.ovf), les disques virtuels (.vmdk ou .vhd) et parfois un fichier de vérification (.mf)', 'Uniquement le disque', 'Uniquement le BIOS'], answer: 1, explain: 'OVF contient plusieurs fichiers : la configuration (.ovf), les disques virtuels (.vmdk ou .vhd) et parfois un fichier de vérification (.mf). Compatible avec plusieurs hyperviseurs.' },
  { id: 'vq317', module: 'v3', q: 'Qu\u2019est-ce que le format OVA ?', options: ['La version compressée de l\u2019OVF : tous les fichiers dans un seul .ova', 'Un hyperviseur', 'Un type de RAID', 'Un protocole réseau'], answer: 0, explain: 'OVA (Open Virtual Appliance) = version compressée du format OVF : tous les fichiers OVF regroupés dans un seul fichier .ova, plus simple à déplacer ou partager.' },

  // ═══ MODULE 4 — Hyperviseurs & techniques ═══
  { id: 'vq401', module: 'v4', q: 'Que fait l\u2019hyperviseur sur la machine physique ?', options: ['Il la formate', 'Il émule/virtualise ses composants en divisant CPU, RAM, disque, cartes réseau et les assigne aux VMs', 'Il installe Windows', 'Il gère uniquement le réseau'], answer: 1, explain: 'Le logiciel hyperviseur émule ou virtualise les composants de la machine physique en divisant le CPU, RAM, disque dur et cartes réseau, et assigne ces ressources aux machines virtuelles (guest).' },
  { id: 'vq402', module: 'v4', q: 'Où s\u2019exécute un hyperviseur de type 1 (Bare metal) ?', options: ['À l\u2019intérieur d\u2019un OS hôte', 'Directement sur le hardware', 'Dans le navigateur', 'Sur une baie SAN'], answer: 1, explain: 'L\u2019hyperviseur type 1 s\u2019exécute directement sur le hardware : noyau hôte allégé et optimisé.' },
  { id: 'vq403', module: 'v4', q: 'Quel est l\u2019hyperviseur le plus répandu EN ENTREPRISE ?', options: ['Type 2', 'Type 1 (Bare metal)', 'Les deux également', 'Aucun'], answer: 1, explain: 'Le type 1 (Bare metal) est le modèle d\u2019hyperviseur le plus répandu en entreprise.' },
  { id: 'vq404', module: 'v4', q: 'Avec quelles instructions matérielles l\u2019OS invité n\u2019a plus besoin d\u2019être modifié en type 1 ?', options: ['AMD-V et Intel VT', 'SSE et AVX', 'PCIe', 'NVMe'], answer: 0, explain: 'Pour des processeurs ayant les instructions de virtualisation matérielle (AMD-V et Intel VT), l\u2019OS invité n\u2019a plus besoin d\u2019être modifié.' },
  { id: 'vq405', module: 'v4', q: 'Lequel de ces hyperviseurs est de type 1 ?', options: ['VirtualBox', 'VMware Workstation', 'VMware ESX', 'Parallels Desktop'], answer: 2, explain: 'Exemples type 1 : XEN, Oracle VM, Microsoft Hyper-V, VMware ESX. Workstation, Fusion, QEMU, Virtual PC/Server, VirtualBox, Parallels = type 2.' },
  { id: 'vq406', module: 'v4', q: 'Où s\u2019exécute un hyperviseur de type 2 ?', options: ['Directement sur le hardware', 'À l\u2019intérieur d\u2019un OS hôte (troisième niveau)', 'Dans le cloud', 'Sur le switch'], answer: 1, explain: 'Le type 2 (Host metal) s\u2019exécute à l\u2019intérieur d\u2019un OS hôte, en troisième niveau au-dessus du matériel ; préféré des utilisateurs Laptop/Desktop.' },
  { id: 'vq407', module: 'v4', q: 'Quel est le rôle d\u2019un OS vis-à-vis des ressources ?', options: ['Partager le processeur, la mémoire et les I/O entre plusieurs processus', 'Les masquer totalement', 'Les chiffrer', 'Les dupliquer'], answer: 0, explain: 'Rôle d\u2019un OS : partager le processeur, la mémoire et les I/O des périphériques entre plusieurs processus.' },
  { id: 'vq408', module: 'v4', q: 'Le rôle de l\u2019hyperviseur est de…', options: ['Permettre ces mécanismes de partage à chaque OS invité (croire qu\u2019il est seul), intercepter les interruptions et simuler les interfaces', 'Remplacer l\u2019OS hôte', 'Supprimer les interruptions', 'Virtualiser Internet'], answer: 0, explain: 'L\u2019hyperviseur permet ces mécanismes pour chaque OS invité (qui croit être seul sur la machine), intercepte les communications avec les interruptions et simule de façon logicielle les interfaces.' },
  { id: 'vq409', module: 'v4', q: 'Dans la virtualisation complète, l\u2019OS invité…', options: ['Doit être modifié', 'N\u2019a pas conscience d\u2019être virtualisé et n\u2019a aucun moyen de savoir qu\u2019il partage le matériel', 'Partage son noyau avec l\u2019hôte', 'Est un conteneur'], answer: 1, explain: 'Virtualisation complète : l\u2019OS invité n\u2019a pas conscience d\u2019être virtualisé, aucun moyen de savoir qu\u2019il partage le matériel avec d\u2019autres OS ; les OS sont vus comme des ordinateurs à part entière sur le réseau.' },
  { id: 'vq410', module: 'v4', q: 'En paravirtualisation, que doit-on faire des systèmes d\u2019exploitation ?', options: ['Rien', 'Les modifier (insertion de drivers redirigeant les appels système au lieu de les traduire)', 'Les remplacer par Linux', 'Les chiffrer'], answer: 1, explain: 'Paravirtualisation : les OS doivent être modifiés — insertions de drivers permettant de REDIRIGER les appels système au lieu de les traduire ; collaboration étroite hyperviseur/OS requise.' },
  { id: 'vq411', module: 'v4', q: 'Pourquoi la redirection des appels système est-elle intéressante en paravirtualisation ?', options: ['Elle est plus rapide que la traduction, utile pour le matériel très sollicité (disque, réseau)', 'Elle est plus lente mais plus sûre', 'Elle supprime le besoin de RAM', 'Elle chiffre les données'], answer: 0, explain: 'Les drivers backend/frontend ne font que de la redirection (beaucoup plus rapide que la traduction) : intelligent pour le matériel potentiellement très sollicité (disque dur, interface réseau…).' },
  { id: 'vq412', module: 'v4', q: 'Quel est l\u2019inconvénient du mécanisme backend/frontend de la paravirtualisation ?', options: ['Dépendance : si l\u2019OS 1 (driver backend) tombe en panne, l\u2019OS 2 ne peut plus accéder au matériel', 'Il est incompatible avec Linux', 'Il double la consommation CPU', 'Il casse le réseau'], answer: 0, explain: 'Inconvénient : dépendance d\u2019un OS virtualisé vis-à-vis d\u2019un autre — si l\u2019OS 1 (backend) tombe en panne, l\u2019OS 2 ne pourra plus accéder au matériel.' },

  // ═══ MODULE 5 — Types de virtualisation ═══
  { id: 'vq501', module: 'v5', q: 'La virtualisation de l\u2019OS comprend…', options: ['Virtualisation de serveurs et de postes de travail (VDI, streaming d\u2019OS)', 'Uniquement les conteneurs', 'Uniquement le RAID', 'La 5G'], answer: 0, explain: 'Virtualisation de l\u2019OS = virtualisation de serveurs + virtualisation des postes de travail (VDI et streaming d\u2019OS).' },
  { id: 'vq502', module: 'v5', q: 'La virtualisation de serveurs consiste à…', options: ['Faire fonctionner simultanément plusieurs serveurs virtuels sur un seul serveur physique', 'Acheter plus de serveurs', 'Dupliquer le réseau', 'Remplacer les NAS'], answer: 0, explain: 'Virtualisation de serveurs : faire fonctionner simultanément, sur un seul serveur physique, plusieurs serveurs virtuels.' },
  { id: 'vq503', module: 'v5', q: 'Quels sont des bénéfices de la virtualisation de serveurs ?', options: ['Meilleure utilisation des capacités, moins de surface au sol, économies, délais réduits, administration simplifiée…', 'Plus de climatisation nécessaire', 'Plus d\u2019administrateurs', 'Plus de coûts électriques'], answer: 0, explain: 'Avantages : meilleure utilisation de la capacité, réduction surface au sol/équipements/climatisation/administrateurs, économies, délais de mise à disposition réduits, administration simplifiée, niveau de service amélioré, migration simplifiée.' },
  { id: 'vq504', module: 'v5', q: 'Dans le VDI, avec quoi les utilisateurs interagissent-ils ?', options: ['Directement avec le BIOS', 'Via un protocole de bureau à distance (RDP, Citrix ICA)', 'Par câble série', 'Via NFS'], answer: 1, explain: 'VDI : les utilisateurs interagissent avec la VM via un protocole de bureau à distance (RDP, Citrix ICA) ; tout est exécuté côté serveur.' },
  { id: 'vq505', module: 'v5', q: 'Un avantage du VDI est…', options: ['La sécurité centralisée : les données et applications restent dans le centre de données', 'Des postes clients plus chers', 'Des mises à jour locales obligatoires', 'Plus de stockage local'], answer: 0, explain: 'Avantages VDI : flexibilité et accès à distance, sécurité centralisée (données dans le datacenter), simplification de la gestion (mises à jour centralisées).' },
  { id: 'vq506', module: 'v5', q: 'Dans le streaming d\u2019OS, où l\u2019OS est-il exécuté côté client ?', options: ['Sur le disque dur local', 'En mémoire (streamé en temps réel au démarrage)', 'Dans le BIOS', 'Sur le NAS'], answer: 1, explain: 'Au démarrage de l\u2019appareil client, l\u2019OS est envoyé en temps réel (streamé) sur le client, où il est exécuté en mémoire ; pas besoin de stockage local pour l\u2019OS.' },
  { id: 'vq507', module: 'v5', q: ' Quelle différence principale entre virtualisation de sessions et VDI ?', options: ['En sessions, tous les utilisateurs partagent le même OS dans des sessions isolées ; en VDI, chacun a sa VM avec OS dédié', 'Aucune différence', 'Les sessions utilisent des VM', 'Le VDI ne permet pas l\u2019accès distant'], answer: 0, explain: 'Virtualisation de sessions : plusieurs utilisateurs connectés simultanément à un serveur, chacun avec une session indépendante sur un OS PARTAGÉ. VDI : environnement VM avec OS DÉDIÉ par utilisateur.' },
  { id: 'vq508', module: 'v5', q: 'Les bulles applicatives (conteneurs d\u2019application) sont…', options: ['Une virtualisation légère : applications isolées partageant le même OS sous-jacent', 'Des VM complètes', 'Un type de RAID', 'Un protocole SAN'], answer: 0, explain: 'Virtualisation par isolation ou bulles applicatives : méthode légère exécutant des applications dans des environnements isolés tout en partageant le même OS sous-jacent. Exemples : UNIX chroot, LXC.' },
  { id: 'vq509', module: 'v5', q: 'La virtualisation de réseaux consiste à…', options: ['Découpler les fonctions et services réseau de l\u2019infrastructure physique sous-jacente', 'Remplacer les câbles par du wifi', 'Supprimer les pare-feux', 'Doublé le débit'], answer: 0, explain: 'Virtualisation de réseaux : créer des versions virtuelles de ressources réseau, découpler les fonctions/services de l\u2019infrastructure physique pour flexibilité, scalabilité et gestion simplifiée.' },
  { id: 'vq510', module: 'v5', q: 'Quels équipements facilitent la virtualisation de réseaux ?', options: ['VMware vSwitch, Open vSwitch ; pare-feu virtuel Cisco ASA Virtual Firewall ; routeur virtuel Cisco CSR 1000V', 'RAID et NAS', 'VirtualBox et VMware', 'Docker et Kubernetes'], answer: 0, explain: 'VMware vSwitch et Open vSwitch facilitent l\u2019abstraction ; Cisco ASA Virtual Firewall protège les flux ; Cisco CSR 1000V permet des routeurs virtuels sur un seul appareil.' },
  { id: 'vq511', module: 'v5', q: 'Pourquoi les réseaux virtuels sont-ils isolés les uns des autres ?', options: ['Pour que le trafic d\u2019un réseau n\u2019interfère pas avec un autre (renforce la sécurité des données)', 'Pour économiser les IP', 'Par obligation légale', 'Pour accélérer la 4G'], answer: 0, explain: 'Les réseaux virtuels sont isolés : le trafic d\u2019un réseau n\u2019interfère pas avec un autre, ce qui renforce la sécurité des données.' },

  // ═══ MODULE 6 — Stockage ═══
  { id: 'vq601', module: 'v6', q: 'La virtualisation du stockage fait apparaître plusieurs périphériques physiques comme…', options: ['Plusieurs disques séparés', 'Un seul et unique périphérique de stockage (pool/datastore)', 'Un réseau', 'Une sauvegarde'], answer: 1, explain: 'Plusieurs périphériques de stockage physiques regroupés apparaissent comme un seul périphérique ; l\u2019espace regroupé est présenté aux hôtes comme un pool (datastore).' },
  { id: 'vq602', module: 'v6', q: 'Parmi les avantages de la virtualisation du stockage :', options: ['Homogénéisation, temps d\u2019arrêt réduits, HA, VMotion, extension automatisée', 'Plus de sauvegarde nécessaire', 'Disques plus chers', 'Panne systémique'], answer: 0, explain: 'Avantages : homogénéisation du stockage (capacités/vitesses différentes), temps d\u2019arrêt réduits, optimisation des performances, HA, migration à chaud (VMotion), extension de capacité automatisée.' },
  { id: 'vq603', module: 'v6', q: 'Que signifie DAS ?', options: ['Direct Attached Storage : stockage directement connecté au serveur, sans passer par un réseau', 'Digital Access System', 'Dynamic Array Storage', 'Disk Allocation Server'], answer: 0, explain: 'DAS (Direct Attached Storage) : stockage directement connecté au serveur ou ordinateur au lieu de transiter par un réseau. Interfaces : SCSI, SATA, SAS.' },
  { id: 'vq604', module: 'v6', q: 'Quelles sont les 3 technologies de connexion DAS citées ?', options: ['SCSI, SATA, SAS', 'NFS, SMB, AFP', 'FC, iSCSI, NVMe', 'USB, HDMI, RJ45'], answer: 0, explain: 'DAS : 1) SCSI (Small Computer System Interface), 2) SATA (Serial Advanced Technology Attachment), 3) SAS (Serial Attached SCSI).' },
  { id: 'vq605', module: 'v6', q: 'Quels sont des inconvénients du DAS ?', options: ['Espace non dynamique, taux d\u2019utilisation non optimal, indisponibilité considérable, pas de VMotion/HA, pas de gestion centralisée', 'Trop cher', 'Trop rapide', 'Nécessite Fibre Channel'], answer: 1, explain: 'Inconvénients DAS : espace non dynamique, taux d\u2019utilisation non optimal, temps d\u2019indisponibilité considérable, fonctionnalités évoluées (VMotion, HA) non disponibles, pas de gestion centralisée des VM.' },
  { id: 'vq606', module: 'v6', q: 'Le NAS se configure comment ?', options: ['Avec clavier et écran', 'Via une interface web accessible depuis un navigateur ; le NAS possède sa propre adresse IP', 'Par UART', 'Via le BIOS'], answer: 1, explain: 'Le NAS n\u2019a ni clavier ni écran : configuration via une interface web ; il possède sa propre adresse IP (nœud du réseau à part entière).' },
  { id: 'vq607', module: 'v6', q: 'Quel protocole est le PLUS utilisé dans les NAS ?', options: ['AFP', 'CIFS/SMB', 'NFS', 'SCSI'], answer: 2, explain: 'NFS : protocole de partage de fichiers Unix, standard universel — le protocole le plus courant dans les NAS (rapide, compatible avec beaucoup de systèmes).' },
  { id: 'vq608', module: 'v6', q: 'Quel protocole NAS est utilisé par Windows ?', options: ['NFS', 'CIFS / SMB (et Samba sur Linux)', 'AFP', 'Fibre Channel'], answer: 1, explain: 'CIFS/SMB : utilisé par Windows (et par Samba sur Linux). AFP est pour Apple.' },
  { id: 'vq609', module: 'v6', q: 'Quels éléments un NAS peut-il stocker pour les hôtes ESXi ?', options: ['Fichiers des VMs (VMDK, snapshots) et ISO des OS', 'Uniquement des documents bureautiques', 'Le BIOS des serveurs', 'Les routes réseau'], answer: 0, explain: 'Le NAS fournit un datastore centralisé pour les hôtes ESXi : fichiers des VMs (disques VMDK, snapshots…) et ISO des systèmes d\u2019exploitation.' },
  { id: 'vq610', module: 'v6', q: 'Au niveau de quoi le SAN fonctionne-t-il ?', options: ['Fichiers', 'Bloc (accès direct aux disques, secteurs)', 'Paquets IP', 'Sessions'], answer: 1, explain: 'Contrairement au NAS (fichiers), le SAN fonctionne au niveau BLOC : accès direct aux disques, au niveau des secteurs ; le stockage apparaît comme un disque dur local.' },
  { id: 'vq611', module: 'v6', q: 'De quoi un SAN est-il composé ?', options: ['Serveurs, switchs SAN, baie de stockage', 'NAS et DAS', 'Uniquement des câbles SATA', 'Un routeur wifi'], answer: 0, explain: 'SAN composé de : des serveurs (utilisent le stockage), des switchs SAN (font le lien), une baie de stockage (contient les disques). Configuration via l\u2019interface du constructeur (Dell EMC, NetApp, HPE).' },
  { id: 'vq612', module: 'v6', q: 'Quels sont les deux principaux protocoles de transit des données dans un SAN ?', options: ['Fibre Channel et iSCSI', 'NFS et SMB', 'SCSI et SATA', 'AFP et CIFS'], answer: 0, explain: 'Les deux principaux protocoles du SAN : Fibre Channel et iSCSI (Internet Small Computer System Interface).' },
  { id: 'vq613', module: 'v6', q: 'Qu\u2019apporte Fibre Channel par rapport à iSCSI ?', options: ['Latence et débit bien meilleurs (fibres optiques), mais à un prix plus élevé', 'Moins de débit mais gratuit', 'Il fonctionne en mode fichier', 'Il est plus simple à configurer'], answer: 0, explain: 'Fibre Channel : baie dédiée + fibres optiques, latence et débit bien meilleurs que iSCSI, prix plus élevé. Principe d\u2019utilisation identique à un SAN iSCSI.' },
  { id: 'vq614', module: 'v6', q: 'Qu\u2019est-ce que IET mentionné dans le cours ?', options: ['iSCSI Enterprise Target : logiciel permettant à un serveur Linux classique de servir de cible iSCSI', 'Un protocole fibre', 'Un type de NAS', 'Une distribution Linux'], answer: 0, explain: 'Comme NFS, iSCSI peut être implémenté par une baie dédiée (meilleures performances) ou par un serveur classique avec le logiciel adéquat, par exemple IET (iSCSI Entreprise Target) sous Linux.' },
  { id: 'vq615', module: 'v6', q: 'La formule du cours pour résumer :', options: ['NAS = partage de fichiers ; SAN = partage de disques', 'NAS = disques ; SAN = fichiers', 'NAS = bloc ; SAN = fichier', 'NAS et SAN sont identiques'], answer: 0, explain: 'NAS = partage de fichiers (comme un disque réseau) ; SAN = partage de disques (comme si chaque serveur avait un gros disque dur externe très rapide).' },

  // ═══ MODULE 7 — RAID ═══
  { id: 'vq701', module: 'v7', q: 'Quels critères de qualité du stockage le RAID vise-t-il ?', options: ['Tolérance aux pannes, disponibilité, fiabilité, performances', 'Couleur et design', 'Bruit et consommation', 'Compatibilité Windows uniquement'], answer: 0, explain: 'Le RAID assure des critères de qualité sur le stockage : tolérance aux pannes, disponibilité, fiabilité, performances — via redondance, répartition, contrôleur RAID.' },
  { id: 'vq702', module: 'v7', q: 'Que signifie l\u2019acronyme actuel RAID ?', options: ['Redundant Array of Independent Disks', 'Random Access Indexed Disk', 'Rapid Array of Internal Drives', 'Redundant Access to Internet Disks'], answer: 0, explain: 'Initialement « Redundant Array of Inexpensive Disks », puis « Redundant Array of Independent Disks » : ensemble redondant de disques indépendants.' },
  { id: 'vq703', module: 'v7', q: 'Où et quand le concept RAID a-t-il été lancé ?', options: ['En 1987 à l\u2019université de Berkeley', 'En 1998 chez VMware', 'En 2013 par Docker', 'En 1979 aux Bell Labs'], answer: 0, explain: 'Le concept du RAID fut lancé en 1987 à l\u2019université de Berkeley par un article décrivant six manières de regrouper des disques (niveaux 0 à 5).' },
  { id: 'vq704', module: 'v7', q: 'Comment fonctionne le RAID logiciel ?', options: ['Un driver de l\u2019OS combine plusieurs disques en un lecteur logique, en utilisant mémoire et CPU du système', 'Un circuit dédié sur la carte mère', 'Un NAS', 'Un switch SAN'], answer: 0, explain: 'Solution logicielle : dépend de l\u2019OS, utilise les ressources mémoire et CPU — un driver combine plusieurs disques en un seul lecteur logique.' },
  { id: 'vq705', module: 'v7', q: 'Qu\u2019apporte le RAID matériel ?', options: ['Un circuit contrôleur RAID (souvent intégré à la carte mère) qui contrôle la grappe et allège le processeur', 'Plus de RAM', 'Un second OS', 'Un cloud privé'], answer: 0, explain: 'Solution matérielle : indépendante de l\u2019OS, recourt à un circuit contrôleur RAID (de plus en plus intégré à la carte mère) contrôlant les commandes envoyées à la grappe (cluster) de disques — allège le travail du processeur.' },
  { id: 'vq706', module: 'v7', q: 'Pourquoi dit-on du RAID 0 qu\u2019on devrait parler de « AID » ?', options: ['Parce qu\u2019il n\u2019ajoute pas de redondance pour être plus fiable', 'Parce qu\u2019il aide les admins', 'Parce qu\u2019il est inférieur à 1', 'Parce qu\u2019il est sans disque'], answer: 0, explain: 'RAID 0 (striping, min. 2 disques) : au lieu de parler de RAID, on devrait parler de « AID » puisque l\u2019on n\u2019ajoute pas de redondance pour être plus fiable.' },
  { id: 'vq707', module: 'v7', q: 'Comment les données sont-elles réparties en RAID 0 ?', options: ['Dupliquées sur 2 disques', 'Découpées en bandes (strips) d\u2019un nombre fixe de secteurs, réparties entre les disques', 'Chiffrées', 'Stockées dans le cache'], answer: 1, explain: 'RAID 0 : les données sont découpées en bandes (strips) constituées d\u2019un nombre fixe de secteurs, réparties entre les disques pour partager le travail ; une requête I/O sur plusieurs bandes sollicite plusieurs disques simultanément.' },
  { id: 'vq708', module: 'v7', q: 'Que se passe-t-il si un disque RAID 0 tombe en panne ?', options: ['Rien', 'La totalité des données est perdue', 'Le second disque prend le relais', 'La parité reconstruit'], answer: 1, explain: 'RAID 0 augmente la vitesse de transferts mais n\u2019assure pas la sécurité des données : si un disque tombe en panne, la totalité des données est perdue.' },
  { id: 'vq709', module: 'v7', q: 'Que fait le RAID 1 (mirroring) si un disque tombe en panne ?', options: ['Tout est perdu', 'L\u2019autre disque contenant la copie prend le relais, sans éteindre l\u2019ordinateur (continuité de service)', 'Le système redémarre', 'Le RAID passe en 0'], answer: 1, explain: 'RAID 1 : duplication sur deux disques ; si un disque tombe en panne, l\u2019autre prend le relais, même sans éteindre l\u2019ordinateur — tolérance de pannes assurant la continuité du service.' },
  { id: 'vq710', module: 'v7', q: 'En RAID 1, de quoi dépend la durée des écritures ?', options: ['Du disque le plus lent', 'Du CPU', 'Du cache', 'Du réseau'], answer: 0, explain: 'RAID 1 : les performances sont semblables à un disque unique ; pour les écritures, c\u2019est du disque le plus lent que dépend la durée ; les lectures peuvent être réparties pour améliorer la bande passante.' },
  { id: 'vq711', module: 'v7', q: 'Le RAID 5 est qualifié de…', options: ['Sécurisé / Performant / Bas coût', 'Rapide / Dangereux / Cher', 'Lent / Sûr / Gratuit', 'Simple / Brutal / Économique'], answer: 0, explain: 'RAID 5 : sécurisé (parité répartie permettant la reconstruction si un disque tombe), performant (lectures rapides, écritures légèrement plus lentes à cause du calcul de parité), bas coût (moins de disques que RAID 1).' },
  { id: 'vq712', module: 'v7', q: 'Que combinent RAID 10 et RAID 0+1 ?', options: ['Le RAID 1 et le RAID 0 : sécurité (1) + vitesse (0)', 'RAID 5 et RAID 6', 'Le DAS et le NAS', 'RAID logiciel et matériel'], answer: 0, explain: 'Certains constructeurs proposent des RAID à deux niveaux combinant RAID 1 et RAID 0 pour assurer simultanément sécurité (RAID 1) et vitesse (RAID 0).' },

  // ═══ MODULE 8 — Datacenter & solutions ═══
  { id: 'vq801', module: 'v8', q: 'Quels équipements constituent un datacenter ?', options: ['Mainframes, serveurs, baies de stockage, équipements réseau et télécommunications', 'Uniquement des PC de bureau', 'Uniquement des NAS', 'Des smartphones'], answer: 0, explain: 'Datacenter = ensemble d\u2019équipements constituant le système d\u2019information : mainframes (charges importantes et critiques), serveurs, baies de stockage, équipements réseaux et télécommunications.' },
  { id: 'vq802', module: 'v8', q: 'Quelle est l\u2019exigence de fonctionnement d\u2019un datacenter ?', options: ['8h/jour en semaine', '24h/24 et 365 jours par an', 'Uniquement la nuit', 'À la demande'], answer: 1, explain: 'Afin d\u2019assurer la disponibilité et la sécurité des données stockées, un datacenter doit être en fonctionnement 24h/24 et 365 jours par an.' },
  { id: 'vq803', module: 'v8', q: 'Qu\u2019est-ce qu\u2019un cluster dans un datacenter ?', options: ['Des serveurs similaires regroupés sur le même réseau/stockage, gérés comme une entité unique', 'Un câble spécial', 'Un type de RAID', 'Une salle climatisée'], answer: 0, explain: 'Cluster : serveurs configurés de manière similaire, regroupés avec connexions au même réseau et au même stockage ; le cluster gère les ressources de tous ses serveurs et agit comme une entité unique.' },
  { id: 'vq804', module: 'v8', q: 'Quel est le bénéfice principal du clustering ?', options: ['Si l\u2019un des serveurs tombe en panne, un autre peut prendre sa place', 'Le réseau va plus vite', 'Moins de câbles', 'Plus d\u2019espace disque'], answer: 0, explain: 'Bénéfice : si l\u2019un des serveurs tombe en panne, un autre serveur peut prendre sa place.' },
  { id: 'vq805', module: 'v8', q: 'Comment un datacenter se protège-t-il des risques naturels (inondation, séisme, incendie) ?', options: ['Étude géographique de l\u2019emplacement + sauvegardes régulières et duplication', 'En ignorant le risque', 'En doublant les claviers', 'En supprimant le cloud'], answer: 0, explain: 'Risques naturels : étude géographique de l\u2019emplacement, sauvegardes régulières et duplication. (Surchauffe → climatisation ; coupure → diversifier les sources d\u2019alimentation ; humaines → contrôle d\u2019accès ; connexion → dupliquée et sécurisée).' },
  { id: 'vq806', module: 'v8', q: 'Quelles mesures de sécurité physiques et logiques un datacenter met-il en place ?', options: ['Badge, empreinte, verrouillage automatique, capteurs vidéo/thermiques, détection d\u2019intrusion, pare-feu, antivirus, chiffrement', 'Uniquement des mots de passe', 'Rien', 'Uniquement des caméras'], answer: 0, explain: 'Protection : contrôle d\u2019accès (badge, empreinte), verrouillage automatique des points d\u2019accès, surveillance (capteurs vidéo, thermiques, proximité), identification du personnel, détection/prévention d\u2019intrusions, pare-feu, antivirus, chiffrement des données.' },
  { id: 'vq807', module: 'v8', q: 'Quelle entreprise a développé la PREMIÈRE solution de virtualisation x86 commerciale ?', options: ['Microsoft', 'VMware (fondée en 1998)', 'Citrix', 'Oracle'], answer: 1, explain: 'Fondée en 1998, VMware a été la première entreprise à développer une solution de virtualisation x86 disponible dans le commerce.' },
  { id: 'vq808', module: 'v8', q: 'Quels produits VMware sont sortis en 2001 ?', options: ['ESX 1.0 (type 1) et GSX 1.0 (type 2)', 'ESXi uniquement', 'vSphere et vCenter', 'Workstation et Fusion'], answer: 0, explain: 'En 2001 : ESX 1.0 (hyperviseur de type 1) et GSX 1.0 (hyperviseur de type 2).' },
  { id: 'vq809', module: 'v8', q: 'Quelle différence entre ESX et ESXi ?', options: ['ESXi a le même noyau d\u2019hyperviseur mais sans la console de service basée Linux', 'ESXi est de type 2', 'ESX est plus récent', 'Aucune différence'], answer: 0, explain: 'L\u2019architecture d\u2019origine d\u2019ESX avait deux parties : l\u2019hyperviseur + un module de console basé Linux. ESXi a le même noyau d\u2019hyperviseur mais sans la console de service. Depuis la v5 (2011), seule ESXi est disponible.' },
  { id: 'vq810', module: 'v8', q: 'Que fait vMotion ?', options: ['Migre des VM d\u2019un hôte ESXi à un autre sans temps d\u2019arrêt', 'Sauvegarde les VMs', 'Clone une VM', 'Redémarre les VMs en panne'], answer: 0, explain: 'vMotion : fonctionnalité permettant de migrer des VM d\u2019un hôte ESXi à un autre sans temps d\u2019arrêt. (HA redémarre automatiquement les VM sur d\u2019autres hôtes en cas de défaillance ; vCenter gère le datacenter virtualisé ; vSphere Client se connecte au vCenter).' },
  { id: 'vq811', module: 'v8', q: 'Quel est le rôle du Dom0 dans Citrix Xen ?', options: ['Invité spécial démarré au boot : privilèges de gestion, accès direct au matériel, gère toutes les E/S des invités', 'Une VM de test', 'Un serveur web', 'Le BIOS de Xen'], answer: 0, explain: 'Le modèle Xen a un invité spécial appelé Domaine 0 (Dom0), démarré lors du démarrage de l\u2019hyperviseur : privilèges de gestion différents, accès direct au matériel, gère toutes les E/S pour les invités individuels.' },
  { id: 'vq812', module: 'v8', q: 'KVM supporte…', options: ['La virtualisation complète ET la paravirtualisation', 'Uniquement la paravirtualisation', 'Uniquement les conteneurs', 'Uniquement Windows'], answer: 0, explain: 'KVM (Kernel-based Virtual Machine) prend en charge à la fois la virtualisation complète et la paravirtualisation ; open source intégré au noyau Linux depuis 2.6.20 ; en réalité une combinaison QEMU-KVM (KVM est issu de QEMU dont il utilise une version modifiée).' },
  { id: 'vq813', module: 'v8', q: 'Quand Hyper-V a-t-il été publié ?', options: ['2005 avec Virtual Server', '2008, partie installable de Windows Server 2008', '2013', '1998'], answer: 1, explain: 'Microsoft a débuté avec Virtual Server en 2005 ; Hyper-V a été publié en 2008 en tant que partie installable de Windows Server 2008.' },
  { id: 'vq814', module: 'v8', q: 'Quel est le mode réseau PAR DÉFAUT de VirtualBox ?', options: ['Bridgé', 'NAT', 'Host-Only', 'none'], answer: 1, explain: 'NAT est la manière la plus simple d\u2019accéder à un réseau externe (aucune configuration requise) : c\u2019est le mode réseau par défaut de VirtualBox.' },
  { id: 'vq815', module: 'v8', q: 'En mode NAT VirtualBox, les VMs peuvent-elles se parler et être contactées ?', options: ['Oui, librement', 'Non : par défaut elles ne peuvent pas se parler ni être contactées de l\u2019extérieur (sécurité maximale)', 'Seulement en IPv6', 'Seulement avec un bridge'], answer: 1, explain: 'Le routeur NAT se place entre chaque VM et l\u2019hôte ; cette séparation maximise la sécurité : par défaut, les VMs ne peuvent pas se parler ni être contactées de l\u2019extérieur.' },
  { id: 'vq816', module: 'v8', q: 'Que permet le réseau bridgé ?', options: ['La VM se comporte comme si elle était physiquement connectée au réseau (hôte et extérieur peuvent la contacter)', 'Couper Internet', 'Uniquement l\u2019accès hôte-VM', 'Aucun réseau'], answer: 0, explain: 'Bridgé : VirtualBox intercepte les données du réseau physique et crée une nouvelle interface logicielle — comme si l\u2019invité était connecté avec un câble ; l\u2019hôte peut lui envoyer/recevoir des données ; VMs contactables depuis l\u2019hôte et l\u2019extérieur.' },
  { id: 'vq817', module: 'v8', q: 'Que permet le réseau Host-Only ?', options: ['Les VMs communiquent entre elles et avec l\u2019hôte UNIQUEMENT (pas d\u2019accès externe ni Internet)', 'L\u2019accès Internet uniquement', 'Le routage NAT', 'Le partage de fichiers NAS'], answer: 0, explain: 'Host-Only : les VMs peuvent communiquer uniquement entre elles et avec l\u2019hôte ; elles ne peuvent pas accéder au réseau externe, à Internet, ni communiquer avec des machines hors de l\u2019hôte.' },

  // ═══ MODULE 9 — Cloud (complément) ═══
  { id: 'vq901', module: 'v9', q: 'Quelle technologie rend possible le cloud computing selon le cours ?', options: ['La virtualisation', 'La 5G', 'Le quantum', 'La fibre'], answer: 0, explain: 'La technologie de virtualisation rend possible le cloud computing (les fournisseurs créent des environnements virtuels sur leurs datacenters).' },
  { id: 'vq902', module: 'v9', q: 'Dans le modèle IaaS, qui gère le système d\u2019exploitation ?', options: ['Le fournisseur', 'Le client (vous gérez OS, middleware et applications)', 'Personne', 'L\u2019hyperviseur'], answer: 1, explain: 'IaaS : le fournisseur fournit l\u2019infrastructure virtualisée (VMs, stockage, réseau) ; le client gère l\u2019OS, le middleware et les applications (ex. Amazon EC2, Azure VMs, GCE).' },
  { id: 'vq903', module: 'v9', q: 'Avec le PaaS, que gère le client ?', options: ['L\u2019infrastructure physique', 'Uniquement ses applications et ses données', 'Le BIOS', 'Le réseau du datacenter'], answer: 1, explain: 'PaaS : le fournisseur fournit la plate-forme (runtime, BDD, middleware) ; le client ne gère que ses applications et données (ex. Heroku, Google App Engine).' },
  { id: 'vq904', module: 'v9', q: 'Gmail ou Office 365 sont des exemples de…', options: ['IaaS', 'PaaS', 'SaaS', 'On-premise'], answer: 2, explain: 'SaaS : l\u2019application complète est consommée en ligne sans installation ni gestion (Gmail, Office 365, Salesforce).' },
  { id: 'vq905', module: 'v9', q: 'Le cloud hybride combine…', options: ['Public + privé liés par des technologies standards', 'Deux clouds privés', 'RAID et NAS', 'Docker et Swarm'], answer: 0, explain: 'Cloud hybride = combinaison public + privé : le cœur sensible reste en privé, l\u2019élasticité vient du public.' },
  { id: 'vq906', module: 'v9', q: 'Quels sont les grands clouds publics cités dans le cours (éditions Docker) ?', options: ['Azure, AWS, GCP', 'Orange et Free', 'OVH uniquement', 'Néant'], answer: 0, explain: 'Le cours cite Cloud (Azure, AWS, GCP) comme plateformes supportées par Docker Community Edition.' },

  // ═══ MODULE 10 — Docker bases ═══
  { id: 'vq1001', module: 'v10', q: 'Un conteneur utilise…', options: ['Son propre kernel Linux', 'Le Kernel de l\u2019OS hôte', 'Un kernel Docker spécial', 'Pas de kernel'], answer: 1, explain: 'Le conteneur utilise le Kernel de l\u2019OS hôte ; il a son propre espace de processus et sa propre interface réseau ; isolé de l\u2019hôte mais exécuté directement dessus.' },
  { id: 'vq1002', module: 'v10', q: 'Parmi les avantages d\u2019un conteneur :', options: ['Démarrage instantané, portabilité multicloud, cohérence Dev/Test/Prod, modularisation, isolation de l\u2019héritage technique', 'Boot de plusieurs minutes', 'Un OS par conteneur', 'Consommation élevée'], answer: 0, explain: 'Avantages : meilleures performances que les VM (démarrage instantané), portabilité (multicloud), cohérence Dev/Test/Prod, modularisation, gestion de l\u2019héritage technique grâce à l\u2019isolation.' },
  { id: 'vq1003', module: 'v10', q: 'En termes de boot : une VM prend quelques…, un conteneur quelques…', options: ['Minutes / secondes', 'Secondes / minutes', 'Heures / minutes', 'Jours / heures'], answer: 0, explain: 'VM : boot assez long (quelques minutes), beaucoup de ressources. Conteneur : boot rapide (quelques secondes), peu de ressources, même kernel (Linux).' },
  { id: 'vq1004', module: 'v10', q: 'Les container engine remplacent-ils les machines virtuelles ?', options: ['Oui, totalement', 'Non : dans la pratique on utilise les deux (VM pour virtualiser les machines, Docker pour isoler les environnements d\u2019exécution)', 'Seulement dans le cloud', 'Seulement sur Mac'], answer: 1, explain: 'Les container engine ne viennent pas remplacer les VM : on utilise les deux pour tirer le bénéfice des deux technologies — VM pour virtualiser les machines, Docker pour isoler les environnements d\u2019exécution dans des VM.' },
  { id: 'vq1005', module: 'v10', q: 'Quelle est l\u2019origine de Docker ?', options: ['Société française (dotCloud, un PaaS avec container engine en Python), maintenant basée à San Francisco', 'Google', 'Microsoft', 'RedHat'], answer: 0, explain: 'L\u2019origine de Docker : société française au départ, maintenant à San Francisco. dotCloud : PaaS avec container engine écrit en Python.' },
  { id: 'vq1006', module: 'v10', q: 'En quelle année Docker a-t-il été réécrit en Go et ouvert en open source ?', options: ['2012 (réécriture Go) et 2013 (open source)', '2008 et 2009', '2015 et 2016', '2010 et 2011'], answer: 0, explain: '2012 : réécriture en Go. 2013 : première version open source, réaction très positive, dotCloud change de nom pour Docker. (2014 : 40 M$ ; 2015 : 95 M$).' },
  { id: 'vq1007', module: 'v10', q: 'Quels problèmes de déploiement Docker résout-il ?', options: ['Compatibilité OS, dépendances aux bonnes versions, environnements Dev/Test/Prod, temps de déploiement, conflits dev/ops', 'La vitesse du réseau', 'Le prix des disques', 'Les pannes électriques'], answer: 0, explain: 'Problèmes avant Docker : compatibilité apps/OS, dépendances et librairies aux bonnes versions par service, installation des environnements Dev/Test/Prod, temps de déploiement, conflits développeurs/opérationnels. Solution : conteneurs avec dépendances embarquées, services séparés.' },
  { id: 'vq1008', module: 'v10', q: 'Quelle est la bonne chaîne de travail Docker ?', options: ['Dockerfile → docker build → image → push/pull → docker run → conteneur', 'Conteneur → image → Dockerfile', 'docker run → Dockerfile → image', 'Image → Dockerfile → build'], answer: 0, explain: 'Le développeur crée un Dockerfile ; docker build construit l\u2019image (contenant tout ce dont l\u2019app a besoin) ; l\u2019image est publiée (push) dans un registre (Docker Hub public ou privé) ; docker pull la télécharge ; docker run instancie et exécute le conteneur (télécharge l\u2019image si absente).' },
  { id: 'vq1009', module: 'v10', q: 'Par quels connecteurs le client Docker se connecte-t-il à Docker Engine ?', options: ['Socket, REST API, etc.', 'Uniquement SSH', 'Uniquement HTTP', 'Par câble série'], answer: 0, explain: 'Le client Docker peut se trouver dans n\u2019importe quelle autre machine et est connecté à Docker Engine via différents connecteurs exposés par Docker (socket, REST API, etc.).' },
  { id: 'vq1010', module: 'v10', q: 'Quelle est la différence entre image et conteneur ?', options: ['L\u2019image est le fichier package (template) ; le conteneur est une instance de l\u2019image exécutée par le Docker Host', 'Aucune', 'Le conteneur est le template', 'L\u2019image est exécutée directement'], answer: 0, explain: 'Image = fichier package représentant la template des conteneurs (app + dépendances). Conteneur = instance d\u2019une image, exécuté par le Docker Host dans un environnement isolé.' },
  { id: 'vq1011', module: 'v10', q: 'Que se passe-t-il avec `docker run` si l\u2019image n\u2019existe pas localement ?', options: ['Erreur fatale', 'Elle est d\u2019abord téléchargée à partir du docker hub, puis le conteneur est créé et exécuté', 'Un conteneur vide est créé', 'Docker se réinstalle'], answer: 1, explain: 'Avec docker run, si l\u2019image n\u2019existe pas dans le host, elle va procéder au téléchargement avant d\u2019en créer et exécuter un conteneur (capture du cours : « Unable to find image nginx:latest locally → Pulling from library/nginx »).' },
  { id: 'vq1012', module: 'v10', q: 'Que fait l\u2019option -d de docker run ?', options: ['Démarre le conteneur comme service de fond (démon)', 'Supprime le conteneur', 'Affiche les logs', 'Définit un port'], answer: 0, explain: 'docker run -d démarre le conteneur comme service de fond.' },
  { id: 'vq1013', module: 'v10', q: 'Quel est le tag par défaut d\u2019une image si la version n\u2019est pas spécifiée ?', options: ['stable', 'latest', '1.0', 'main'], answer: 1, explain: 'La valeur par défaut de la version de l\u2019image est latest. Pour spécifier la version : docker run image_name:tag (exemple du cours : docker run redis:4.0).' },
  { id: 'vq1014', module: 'v10', q: 'Que fait `docker ps -a` ?', options: ['Liste tous les conteneurs avec leurs statuts (Up, Exited, Created)', 'Liste uniquement les conteneurs actifs', 'Liste les images', 'Supprime les conteneurs'], answer: 0, explain: 'docker ps liste les conteneurs en cours d\u2019exécution (chaque conteneur a un ID unique et un nom) ; docker ps -a liste TOUS les conteneurs avec leur statut (Up, Exited, Created).' },
  { id: 'vq1015', module: 'v10', q: 'Comment mapper les ports au démarrage d\u2019un conteneur nginx ?', options: ['-p port externe:port interne (ex. docker run -d -p 8082:80 nginx)', '--map 80:8082', '-e PORT=8082', '--port-out 8082'], answer: 0, explain: 'Option -p port externe:port interne. Exemple du cours : sudo docker run -d -p 8082:80 nginx — accessible sur http://192.168.57.3:8082 (IP de la VM ubuntu hébergeant le Docker Host).' },
  { id: 'vq1016', module: 'v10', q: 'Avant de supprimer une image avec docker rmi, il faut…', options: ['Stopper et supprimer tous les conteneurs instanciés de cette image', 'Redémarrer Docker', 'Vider le cache', 'Se déconnecter du Hub'], answer: 0, explain: 'docker rmi supprime une image du host : il faut d\u2019abord s\u2019assurer de stopper et supprimer tous les conteneurs instanciés de cette image.' },
  { id: 'vq1017', module: 'v10', q: 'Que se passe-t-il si on fait `docker rm` sur un conteneur en cours d\u2019exécution ?', options: ['Error response from daemon : You cannot remove a running container — il faut le stopper avant', 'Le conteneur est supprimé', 'Le conteneur est mis en pause', 'Docker redémarre'], answer: 0, explain: 'Erreur du cours : « You cannot remove a running container … Stop the container before attempting removal or force remove » — ordre : docker stop af25 PUIS docker rm af25.' },
  { id: 'vq1018', module: 'v10', q: 'Pourquoi `docker run ubuntu` crée-t-il un conteneur qui ne démarre pas (Exited (0)) ?', options: ['Un conteneur est fait pour contenir des processus/services, pas des OS ; l\u2019image ubuntu sert de base à d\u2019autres conteneurs', 'Ubuntu est payant', 'Il manque de la RAM', 'Le port 22 est fermé'], answer: 0, explain: 'Le conteneur sera créé mais pas démarré : un conteneur docker est fait pour contenir des processus et des services et non des OS. L\u2019image ubuntu est faite pour être l\u2019image de base d\u2019autres conteneurs. Quand un service du conteneur s\u2019arrête, le conteneur s\u2019arrête aussi.' },
  { id: 'vq1019', module: 'v10', q: 'Que fait `docker exec -it my2 mysql --password` ?', options: ['Exécute une commande mysql DANS le conteneur démarré my2, en mode interactif (les résultats arrivent sur le terminal)', 'Démarre un conteneur mysql', 'Supprime my2', 'Exporte la BDD'], answer: 0, explain: 'docker exec exécute une commande dans un conteneur démarré ; -it = mode itératif/interactif : on se connecte au serveur mysql et on tape les cmds, les résultats sont envoyés sur le terminal (exemple : show databases → information_schema, mysql, performance_schema, sys).' },
  { id: 'vq1020', module: 'v10', q: 'À quoi sert `docker attach containerID` ?', options: ['Attacher la console du terminal courant au conteneur lancé en tâche de fond (-d)', 'Créer un conteneur', 'Lister les conteneurs', 'Copier une image'], answer: 0, explain: 'Quand vous lancez un conteneur comme tâche de fond avec -d, docker attach attache la console du terminal courant au conteneur (exemple du cours : docker run -d alpine ping 8.8.8.8, puis docker attach f486e756d97b).' },
  { id: 'vq1021', module: 'v10', q: 'Que retourne `docker inspect` ?', options: ['Des informations détaillées sur le conteneur au format JSON (Id, Created, State: running…)', 'Uniquement l\u2019état Up/Exited', 'Les logs', 'La taille de l\u2019image'], answer: 0, explain: 'ps donne des informations basiques ; docker inspect <container_name or id> donne plus de détail au format JSON (Id, Created, Path, Args, State: {Status: running, Running: true, Paused: false…}).' },
  { id: 'vq1022', module: 'v10', q: 'Où sont stockées par défaut les données d\u2019un conteneur MySQL ?', options: ['/var/lib/mysql à l\u2019intérieur du conteneur', '/opt/dataDir sur l\u2019hôte', 'Dans le Docker Hub', 'Dans le BIOS'], answer: 0, explain: 'Les données sont stockées par défaut dans /var/lib/mysql à l\u2019intérieur du conteneur, qui dispose de son propre système de fichiers : supprimer le conteneur détruit les BDD.' },
  { id: 'vq1023', module: 'v10', q: 'Comment rendre les données MySQL persistantes ?', options: ['$ docker run -v /opt/dataDir:/var/lib/mysql mysql', '$ docker persist mysql', '$ docker save mysql', '$ docker cp mysql'], answer: 0, explain: 'Le mapping des volumes au démarrage (-v dossier_externe:dossier_interne) monte un dossier hors du conteneur : même si on supprime le conteneur, les données restent dans /opt/dataDir.' },
  { id: 'vq1024', module: 'v10', q: 'Quelle commande affiche le fichier log d\u2019un conteneur de fond ?', options: ['docker logs container_ID', 'docker cat', 'docker tail', 'docker show-log'], answer: 0, explain: '$ docker logs container_ID : utile quand le conteneur est démarré comme tâche de fond.' },

  // ═══ MODULE 11 — Dockerfile, réseau, couches ═══
  { id: 'vq1101', module: 'v11', q: 'Un Dockerfile est…', options: ['Un fichier texte contenant les commandes nécessaires à la construction d\u2019une image', 'Une image compressée', 'Un script de déploiement YAML', 'Un conteneur minimal'], answer: 0, explain: 'Dockerfile = fichier texte avec les commandes nécessaires à la construction d\u2019une image ; docker build crée l\u2019image à partir de ces commandes.' },
  { id: 'vq1102', module: 'v11', q: 'Quelle instruction définit l\u2019image de base ?', options: ['FROM', 'RUN', 'ENTRYPOINT', 'WORKDIR'], answer: 0, explain: 'FROM : définir l\u2019image de base utilisée pour démarrer le processus de construction.' },
  { id: 'vq1103', module: 'v11', q: 'Quelle différence entre COPY et ADD ?', options: ['ADD copie aussi en extrayant des archives ou téléchargeant depuis une URL ; COPY copie simplement depuis le contexte de build', 'Aucune différence', 'COPY télécharge depuis des URL', 'ADD est plus lent et déconseillé'], answer: 0, explain: 'COPY : copie des fichiers/dossiers locaux depuis le contexte de build vers l\u2019image. ADD : copie + peut extraire des archives ou télécharger des fichiers depuis une URL.' },
  { id: 'vq1104', module: 'v11', q: 'Que définit ENTRYPOINT ?', options: ['Le programme ou script TOUJOURS exécuté quand le conteneur démarre, acceptant des arguments supplémentaires', 'Une variable d\u2019environnement', 'Le port exposé', 'L\u2019utilisateur du conteneur'], answer: 0, explain: 'ENTRYPOINT définit le programme ou script qui sera toujours exécuté quand le conteneur démarre, en acceptant éventuellement des arguments supplémentaires.' },
  { id: 'vq1105', module: 'v11', q: 'À quoi servent USER et WORKDIR ?', options: ['USER : définir l\u2019UID qui exécutera le conteneur ; WORKDIR : définir le chemin où la commande CMD doit être exécutée', 'USER : créer un utilisateur Linux ; WORKDIR : monter un volume', 'USER : mot de passe ; WORKDIR : port', 'Aucun intérêt'], answer: 0, explain: 'USER définit l\u2019UID (nom d\u2019utilisateur) qui exécutera le conteneur ; WORKDIR définit le chemin où la commande définie avec CMD doit être exécutée. VOLUME déclare un dossier persistant.' },
  { id: 'vq1106', module: 'v11', q: 'Dans l\u2019exemple du cours (site statique), le Dockerfile est :', options: ['FROM nginx / COPY index.html /usr/share/nginx/html / EXPOSE 80', 'FROM ubuntu / RUN nginx', 'FROM node / CMD npm start', 'FROM scratch / ADD index.html'], answer: 0, explain: 'webApp/Dockerfile : FROM nginx, COPY index.html /usr/share/nginx/html, EXPOSE 80 — puis docker build -t myapp . et docker run -d -p 8089:80 myapp.' },
  { id: 'vq1107', module: 'v11', q: 'Quel est le mode réseau PAR DÉFAUT de Docker ?', options: ['bridge', 'host', 'none', 'overlay'], answer: 0, explain: 'Bridge est le mode réseau par défaut utilisé par tout conteneur exécuté : $ docker run nginx. Host : --network=host. none : --network=none.' },
  { id: 'vq1108', module: 'v11', q: 'Quelles adresses ont typiquement les conteneurs sur le réseau bridge par défaut ?', options: ['172.17.0.x', '192.168.1.x', '10.0.0.x', '127.0.0.x'], answer: 0, explain: 'Bridge : réseau privé interne créé par Docker dans le Host ; chaque conteneur a une adresse souvent 172.17.0.x et peut accéder aux autres par cette adresse.' },
  { id: 'vq1109', module: 'v11', q: 'Quel inconvénient le réseau host présente-t-il ?', options: ['On ne peut pas démarrer plusieurs instances du même conteneur (même port exposé au host)', 'Il est lent', 'Il n\u2019existe pas', 'Il chiffre le trafic'], answer: 0, explain: 'En mode host, le port de chaque conteneur est mappé automatiquement au même port du host : impossible d\u2019exposer plusieurs services avec le même port → pas plusieurs instances du même conteneur.' },
  { id: 'vq1110', module: 'v11', q: 'Que signifie le mode réseau none ?', options: ['Le conteneur n\u2019est attaché à aucun réseau : inaccessible ni localement ni de l\u2019extérieur', 'Réseau par défaut', 'Réseau en 172.17', 'Réseau chiffré'], answer: 0, explain: 'none signifie que le conteneur n\u2019est attaché à aucun réseau ; il ne sera donc pas accessible ni localement ni de l\u2019extérieur.' },
  { id: 'vq1111', module: 'v11', q: 'Quelle commande crée un réseau bridge personnalisé (cours) ?', options: ['docker network create --driver bridge --subnet 182.18.0.0/16 custom-isolated-net', 'docker create net bridge', 'docker net new --bridge', 'docker bridge create'], answer: 0, explain: '$ docker network create --driver bridge --subnet 182.18.0.0/16 custom-isolated-net ; docker network ls pour lister ; docker inspect pour la config réseau d\u2019un conteneur (exemple : myNet 172.19.0.0/16 → IPAddress 172.19.0.2, Gateway 172.19.0.1).' },
  { id: 'vq1112', module: 'v11', q: 'Pourquoi est-il plus pratique de connecter les conteneurs par leur nom ?', options: ['Car les adresses IP peuvent changer au démarrage', 'Les noms sont plus courts', 'Les IP sont secrètes', 'Par sécurité'], answer: 0, explain: 'Docker utilise DNS (Docker Name Spaces) pour associer l\u2019IP au nom du conteneur ; plus pratique d\u2019utiliser les noms car les adresses IP peuvent changer au démarrage (DNS démarré par défaut en 172.17.0.11 selon le cours).' },
  { id: 'vq1113', module: 'v11', q: 'Quels dossiers Docker crée-t-il dans /var/lib/docker ?', options: ['aufs, containers, image, volumes', 'bin, etc, usr', 'logs, tmp, cache', 'nginx, mysql, redis'], answer: 0, explain: 'Docker crée son dossier /var/lib/docker avec : aufs, containers, image, volumes — c\u2019est là qu\u2019il stocke par défaut toutes ses données (fichiers relatifs aux images, conteneurs, volumes).' },
  { id: 'vq1114', module: 'v11', q: 'Dans l\u2019exemple d\u2019architecture en couches, que se passe-t-il au 2e build (Dockerfile2) ?', options: ['Les couches 1-3 (ubuntu, apt, pip) sont réutilisées du cache (0 MB) ; seule la couche source (229 B) est recalculée', 'Tout est retéléchargé', 'Les couches sont supprimées', 'L\u2019image double de taille'], answer: 0, explain: 'Couches du 1er build : L1 ubuntu 120 MB, L2 apt 306 MB, L3 pip 6.3 MB, L4 source 229 B, L5 entrypoint 0 MB. Au 2e build, L1-L3 = 0 MB (cache réutilisé), seule L4 (229 B) change — chaque instruction crée une couche.' },

  // ═══ MODULE 12 — Compose, Registry, cgroups ═══
  { id: 'vq1201', module: 'v12', q: 'Qu\u2019est-ce que Docker Compose ?', options: ['Un outil pour définir et exécuter des applications Docker à conteneurs multiples via un fichier YAML (docker-compose.yml)', 'Un langage de programmation', 'Un registre d\u2019images', 'Un hyperviseur'], answer: 0, explain: 'Compose : définir et exécuter des applications multi-conteneurs ; fichier YAML docker-compose.yml ; une seule commande : docker-compose up.' },
  { id: 'vq1202', module: 'v12', q: 'Les 5 services de l\u2019application de vote sont :', options: ['Voting-app (Python), Redis (cache), Worker (Java), PostgreSQL (données), Result-app (résultats)', 'nginx, apache, mysql, php, node', 'Docker, Swarm, K8s, Mesos, cgroups', 'vote, result, db, dns, proxy'], answer: 0, explain: 'Voting-app : web app Python · Redis : cache mémoire · Worker : développé en Java · PostgreSQL : stockage du vote · Result-app : présentation des résultats (source : github.com/eesprit/example-voting-app).' },
  { id: 'vq1203', module: 'v12', q: 'Dans le démarrage manuel, quelle option lie les services ?', options: ['--link', '--connect', '--join', '--net'], answer: 0, explain: 'Démarrage manuel lourd avec docker run + --link : docker run -d --name=vote -p 5000:80 --link=redis:redis eesprit/voting-app-vote, etc. Il est plus simple d\u2019utiliser docker-compose.' },
  { id: 'vq1204', module: 'v12', q: 'Que dit le cours sur l\u2019option links en version 2 de docker-compose ?', options: ['Elle n\u2019est pas obligatoire : Docker crée automatiquement un lien entre tous les services déclarés', 'Elle est obligatoire', 'Elle a été supprimée du YAML', 'Elle remplace les volumes'], answer: 0, explain: 'Dans la version 2 de docker-compose, l\u2019option links n\u2019est pas obligatoire : Docker crée automatiquement un lien entre tous les services déclarés dans docker-compose.' },
  { id: 'vq1205', module: 'v12', q: 'Dans le compose du cours, le service vote utilise quelle image et quel port ?', options: ['eesprit/voting-app-vote avec ports "5000:80"', 'redis:alpine sur 6379', 'postgres:9.4 sur 5432', 'nginx sur 80'], answer: 0, explain: 'vote : image eesprit/voting-app-vote, ports "5000:80" ; redis : redis:alpine (6379) ; db : postgres:9.4 ; result : eesprit/voting-app-result, ports "5001:80" (+ 5858 en mode build).' },
  { id: 'vq1206', module: 'v12', q: 'Que doit contenir un service compose si l\u2019image n\u2019existe pas encore ?', options: ['L\u2019option build: ./dossier pointant vers son Dockerfile', 'Un flag --build-only', 'Un fichier .tar', 'Rien, impossible'], answer: 0, explain: 'Si les images ne sont pas créées, chaque service peut être construit avec build: ./vote, build: ./worker, build: ./result (+ command, volumes, ports).' },
  { id: 'vq1207', module: 'v12', q: 'Dans l\u2019architecture réseau Compose de la voting-app :', options: ['front-end relie voting-app et result-app ; back-end relie redis, db et worker', 'Tout est sur un seul réseau', 'back-end relie voting-app et result', 'Il n\u2019y a pas de réseaux'], answer: 0, explain: 'Front-end Net : voting-app + result-app. Back-end Net : redis, db, worker-app. Déclarés dans la section networks du docker-compose.yml.' },
  { id: 'vq1208', module: 'v12', q: 'Où sont stockées les images docker publiques ?', options: ['Dans le cloud : Docker Hub (docker.io)', 'Sur le BIOS', 'Dans /etc/docker', 'Sur GitHub uniquement'], answer: 0, explain: 'Les images publiques sont stockées dans le cloud : Docker Hub (docker.io). docker run nginx : nginx est le nom de l\u2019image dans un repository du hub.' },
  { id: 'vq1209', module: 'v12', q: 'Comment installer un registre privé (cours) ?', options: ['$ docker run -d -p 5000:5000 --name my-registry registry:2', '$ docker install registry', '$ docker hub --private', '$ docker create registry'], answer: 0, explain: 'Docker registry est lui-même une application exposée en image : docker run -d -p 5000:5000 --name my-registry registry:2, puis docker image tag my-image localhost:5000/my-image, docker push/pull localhost:5000/my-image.' },
  { id: 'vq1210', module: 'v12', q: 'Comment accéder à un registre interne d\u2019organisation (cours) ?', options: ['$ docker login private-registry.io puis $ docker run private-registry.io/apps/internal-app', '$ docker register', '$ docker signin', 'Aucune authentification nécessaire'], answer: 0, explain: 'Les organisations créent leur annuaire interne : l\u2019accès passe par une authentification docker login private-registry.io, puis docker run private-registry.io/apps/internal-app.' },
  { id: 'vq1211', module: 'v12', q: 'Par défaut, un conteneur peut utiliser…', options: ['Toutes les ressources disponibles (CPUs et RAM) du host Linux', '10 % du CPU', '512 Mo de RAM', 'Un demi-cœur'], answer: 0, explain: 'Par défaut, un conteneur peut utiliser toutes les ressources disponibles (CPUs et RAM) dans le host Linux.' },
  { id: 'vq1212', module: 'v12', q: 'Comment restreindre les ressources d\u2019un conteneur (cours) ?', options: ['$ docker run --cpus=0.5 nginx et $ docker run --memory=100m mysql', '$ docker limit cpu 50%', '$ docker cap --cpu', 'Impossible'], answer: 0, explain: 'Restriction des ressources avec cgroups : docker run --cpus=0.5 nginx (demi-CPU) et docker run --memory=100m mysql (100 Mo de RAM).' },

  // ═══ MODULE 13 — Swarm ═══
  { id: 'vq1301', module: 'v13', q: 'Pourquoi démarrer plusieurs instances d\u2019un service ?', options: ['Scalabilité, tolérance aux pannes, disponibilité, montée en charge', 'Pour dépenser plus', 'Uniquement pour le design', 'Pour contourner les licences'], answer: 0, explain: 'Plusieurs instances pour : scalabilité (variation de charge), tolérance aux pannes (continuer malgré pannes matérielles/logicielles/réseau), disponibilité (fonctionnel sans interruption), montée en charge (augmentation du travail).' },
  { id: 'vq1302', module: 'v13', q: 'Que se passe-t-il si Docker Engine tombe en panne sans orchestration ?', options: ['Tous les conteneurs vont crasher', 'Rien', 'Les conteneurs redémarrent', 'Seul le réseau tombe'], answer: 0, explain: 'Si une instance tombe en panne, il faut la remplacer. Si Docker Engine tombe en panne, TOUS les conteneurs vont crasher. L\u2019orchestration est la solution.' },
  { id: 'vq1303', module: 'v13', q: 'Qu\u2019est-ce que l\u2019orchestration des conteneurs ?', options: ['Un ensemble d\u2019outils et de scripts automatisant : scalabilité, réplication, haute disponibilité, bilan de santé des conteneurs', 'Un langage de script', 'Un type de réseau', 'Un fichier YAML'], answer: 0, explain: 'Orchestration = ensemble d\u2019outils et de scripts pour automatiser les opérations : scalabilité (adapter la taille de l\u2019ensemble de conteneurs), réplication, haute disponibilité, bilan de santé. Exemples : Docker Swarm, Kubernetes, MESOS.' },
  { id: 'vq1304', module: 'v13', q: 'Que fait Docker Swarm ?', options: ['Combine plusieurs machines en cluster ; distribue et réplique les instances de services pour la HA et l\u2019équilibre de charges', 'Virtualise le matériel', 'Crée des images', 'Remplace Docker Engine'], answer: 0, explain: 'Swarm combine plusieurs machines pour former un cluster ; il prend en charge la distribution et la réplication des instances de services dans des hosts distribués pour la haute disponibilité et l\u2019équilibre de charges.' },
  { id: 'vq1305', module: 'v13', q: 'Sur quel nœud exécute-t-on les commandes « docker service » ?', options: ['Sur le swarm manager node', 'Sur chaque worker', 'Sur tous les nœuds', 'Sur le NAS'], answer: 0, explain: 'Pour configurer Swarm : démarrer plusieurs hosts docker, désigner un manager et des workers, puis exécuter les commandes docker service sur le swarm manager node (ex. docker service create --replicate=4 -p 8080:80 my-app).' },
  { id: 'vq1306', module: 'v13', q: 'Quelle commande initialise le manager (cours) ?', options: ['$ sudo docker swarm init --advertise-addr 192.168.57.3 --listen-addr 192.168.57.3', '$ docker swarm start', '$ docker cluster create', '$ docker init swarm'], answer: 0, explain: 'docker swarm init --advertise-addr 192.168.57.3 --listen-addr 192.168.57.3 → « Swarm initialized: current node is now a manager » + le token de join pour les workers.' },
  { id: 'vq1307', module: 'v13', q: 'Que signifient advertise-addr et listen-addr ?', options: ['Advertise : où le manager accepte les connexions des autres nœuds ; Listen : adresse d\u2019écoute pour accéder au cluster depuis l\u2019extérieur', 'Advertise : port HTTP ; Listen : port SSH', 'Deux noms pour la même chose', 'Advertise : le DNS ; Listen : le firewall'], answer: 0, explain: 'Advertise-addr : adresse où le swarm manager accepte les connexions à partir des autres nœuds. Listen-addr : adresse d\u2019écoute pour accéder au cluster swarm depuis l\u2019extérieur. Port par défaut de Swarm : 2377.' },
  { id: 'vq1308', module: 'v13', q: 'Quel est le port par défaut de Swarm ?', options: ['2377', '8080', '5000', '2376'], answer: 0, explain: 'Le port par défaut de Swarm est 2377 (docker swarm join … 192.168.57.3:2377).' },
  { id: 'vq1309', module: 'v13', q: 'Quelle commande ajoute un worker (cours) ?', options: ['$ sudo docker swarm join --token SWMTKN-1-… 192.168.57.3:2377', '$ docker swarm add worker', '$ docker node join', '$ docker join swarm'], answer: 0, explain: 'docker swarm join --token SWMTKN-1-… 192.168.57.3:2377 → « This node joined a swarm as a worker. » On refait la même chose sur l\u2019autre machine.' },
  { id: 'vq1310', module: 'v13', q: 'Que montre `docker node ls` sur le manager ?', options: ['ID, HOSTNAME, STATUS (Ready), AVAILABILITY (Active), MANAGER STATUS (Leader), ENGINE VERSION (19.03.1)', 'Les conteneurs', 'Les images', 'Les réseaux'], answer: 0, explain: 'docker node ls liste les nœuds du cluster : host1 (Leader), host2, host3 — Ready / Active / Engine 19.03.1.' },
  { id: 'vq1311', module: 'v13', q: 'Que signifie la sortie « 1/1: running · verify: Service converged » ?', options: ['Toutes les tâches demandées tournent : le service a convergé', 'Le service a échoué', '1 erreur sur 1', 'Le service est en pause'], answer: 1, explain: 'docker service create --name foo alpine ping 8.8.8.8 → overall progress: 1 out of 1 tasks, 1/1: running, verify: Service converged = l\u2019état désiré est atteint.' },
  { id: 'vq1312', module: 'v13', q: 'Que montre `docker service ps foo` ?', options: ['Les tâches du service : NAME (foo.1), IMAGE, NODE (host1), DESIRED/CURRENT STATE', 'Les nœuds du cluster', 'Les logs', 'Les ports'], answer: 0, explain: 'docker service ps foo : ID, NAME (foo.1), IMAGE (alpine:latest), NODE (host1), DESIRED STATE (Running), CURRENT STATE (Running about a minute ago), ERROR, PORTS.' },
  { id: 'vq1313', module: 'v13', q: 'Qu\u2019est-ce qu\u2019un réseau overlay ?', options: ['Réseau utilisé dans des environnements distribués comme Swarm pour la communication entre conteneurs sur DIFFÉRENTS hôtes', 'Le réseau par défaut d\u2019un seul hôte', 'Un réseau sans IP', 'Un câble virtuel'], answer: 0, explain: '--driver overlay : les réseaux overlay sont utilisés dans des environnements distribués comme Docker Swarm pour permettre la communication entre les conteneurs sur différents hôtes. Création chiffrée : docker network create --driver overlay --opt encrypted exquisite.' },
  { id: 'vq1314', module: 'v13', q: 'Dans le déploiement 3 services du cours, comment le service back est-il créé ?', options: ['docker service create --name back --network exquisite --limit-memory 64M --reserve-memory 64M vdemeeester/exquisite-words-java:v1', 'docker run back java', 'docker service create back mongo:3.3.8', 'docker compose up back'], answer: 0, explain: 'back : --network exquisite --limit-memory 64M --reserve-memory 64M vdemeeester/exquisite-words-java:v1 ; mongo : --network exquisite mongo:3.3.8 ; front : --network exquisite -p 808:80 vdemeeester/exquisite-web:v1.' },
  { id: 'vq1315', module: 'v13', q: 'Quelle commande met le service back à l\u2019échelle 15 instances ?', options: ['$ sudo docker service scale back=15', '$ sudo docker scale 15 back', '$ sudo docker service update --replicas 15 back', '$ sudo docker service grow back 15'], answer: 0, explain: 'docker service scale back=15 → « back scaled to 15 » puis overall progress jusqu\u2019à 15/15: running, Service converged. Pareil : scale front=2.' },
  { id: 'vq1316', module: 'v13', q: 'Comment sont les 15 instances back réparties après le scale ?', options: ['Réparties sur les 3 hosts du cluster (ex. 5/5/5)', 'Toutes sur le manager', 'Toutes sur host3', 'Une seule au total'], answer: 1, explain: 'La capture du cours montre les B répartis sur Host 1, Host 2 et Host 3 (avec M et F) : Swarm répartit et équilibre les instances à travers les nœuds.' },
  { id: 'vq1317', module: 'v13', q: 'Quelle commande met à jour le service back progressivement ?', options: ['$ sudo docker service update --update-parallelism 2 --update-delay 10s back', '$ sudo docker service restart back', '$ sudo docker service upgrade back', '$ sudo docker service refresh back --all'], answer: 0, explain: 'Rolling update : docker service update --update-parallelism 2 --update-delay 10s back → mise à jour 2 tâches à la fois, 10 s entre chaque, jusqu\u2019à 15/15: running.' },
  { id: 'vq1318', module: 'v13', q: 'Comment mettre à jour l\u2019image du service front (cours) ?', options: ['$ sudo docker service update --image vdemeeester/exquisite-web:v2 front', '$ sudo docker service pull front', '$ sudo docker image update front', '$ sudo docker service rebuild front'], answer: 0, explain: 'docker service update --image vdemeeester/exquisite-web:v2 front → overall progress: 2 out of 2 tasks, verify: Service converged.' },
  { id: 'vq1319', module: 'v13', q: 'Quelle commande effectue un rollback du service front ?', options: ['$ sudo docker service update --rollback front', '$ sudo docker service undo front', '$ sudo docker service restore front', '$ sudo docker revert front'], answer: 0, explain: 'docker service update --rollback front → « rollback: manually requested rollback », overall progress: rolling back update: 2 out of 2 tasks, verify: Service converged.' },
  { id: 'vq1320', module: 'v13', q: 'Que fait `docker node update --availability drain host3` ?', options: ['Toutes les instances des services déployées dans Host 3 vont MIGRER vers les autres nœuds du cluster', 'Host 3 est supprimé', 'Host 3 double ses instances', 'Le cluster est arrêté'], answer: 0, explain: 'Suspendre un nœud worker : docker node update --availability drain host3 → toutes les instances des services déployées dans le nœud Host 3 migrent vers les autres nœuds du cluster.' },
  { id: 'vq1321', module: 'v13', q: 'Que se passe-t-il avec --constraint engine.label==ssd si aucun nœud ne satisfait la contrainte ?', options: ['1/1: no suitable node (scheduling constraints not satisfied…) — opération continuant en arrière-plan', 'Le service démarre quand même', 'Le cluster tombe', 'Le label est créé automatiquement'], answer: 0, explain: 'docker service create --name svc1 --constraint engine.label==ssd nginx → « no suitable node (scheduling constraints not satisfied on 2 nodes; 1 node …) », Operation continuing in background.' },
  { id: 'vq1322', module: 'v13', q: 'Que fait le mode global ?', options: ['docker service create --mode global alpine ping 8.8.8.8 : une instance sur CHAQUE nœud du cluster', 'Un seul service global', 'Un service chiffré', 'Un service sans réseau'], answer: 0, explain: '--mode global : le service démarre sur chaque nœud (2 out of 2 tasks : tw9is2zomef5: running, ssslatiguj2k: running) — au lieu du mode replicated par défaut.' },

  // ═══ MODULE 14 — Kubernetes ═══
  { id: 'vq1401', module: 'v14', q: 'Que signifie le mot Kubernetes en grec ?', options: ['« Timonier » : celui qui dirige le bateau', '« Navigateur »', '« Pilote automatique »', '« Ancre »'], answer: 0, explain: 'Kubernetes : mot d\u2019origine grecque signifiant « Timonier », celui qui dirige le bateau.' },
  { id: 'vq1402', module: 'v14', q: 'De quel projet Google Kubernetes est-il inspiré ?', options: ['Borg', 'MapReduce', 'BigTable', 'Spanner'], answer: 0, explain: 'Kubernetes est inspiré du projet Borg dont Google se sert depuis des années pour gérer ses conteneurs.' },
  { id: 'vq1403', module: 'v14', q: 'En quel langage Kubernetes est-il écrit ?', options: ['Go', 'Java', 'Python', 'C++'], answer: 0, explain: 'Kubernetes est écrit en langage Go ; développé par Google avec ses partenaires (Redhat, CoreOS, IBM, Microsoft, MesoSphere, Vmware, HP…).' },
  { id: 'vq1404', module: 'v14', q: 'Quel est l\u2019objectif de Kubernetes ?', options: ['Gérer directement des APPLICATIONS et non pas des machines (indépendamment de l\u2019infrastructure)', 'Virtualiser le matériel', 'Remplacer Docker', 'Créer des images'], answer: 0, explain: 'L\u2019objectif est de gérer directement des applications et non pas des machines : gestion des applications indépendamment de l\u2019infrastructure. Kubernetes REST API expose ses fonctionnalités.' },
  { id: 'vq1405', module: 'v14', q: 'Que peut-on faire avec Kubernetes ?', options: ['Déployer vite et de façon prévisible, répliquer, load balancer, déclarer une cible et la maintenir, mettre à jour sans interruption, auto-réparation', 'Uniquement héberger des sites statiques', 'Remplacer le DNS', 'Créer des VMs'], answer: 0, explain: 'Capacités : déploiement rapide/prévisible de conteneurs, automatisation du déploiement et de la réplication, groupes + load balancing, architecture cible déclarée et maintenue, mises à jour sans interruption, séparation app/infrastructure, détection et résolution automatique des problèmes.' },
  { id: 'vq1406', module: 'v14', q: 'Qu\u2019est-ce qu\u2019un Node dans Kubernetes ?', options: ['Une machine physique ou virtuelle dans laquelle seront déployés des Pods (doit exécuter un Container Engine comme Docker)', 'Un conteneur', 'Un réseau', 'Un fichier YAML'], answer: 0, explain: 'Node : machine physique ou virtuelle où seront déployés des Pods ; chaque Node doit exécuter un Container Engine comme Docker.' },
  { id: 'vq1407', module: 'v14', q: 'À quoi sert kubectl ?', options: ['Application en ligne de commande pour interagir avec Kubernetes (déployer, inspecter, gérer les ressources, consulter les logs)', 'Créer des images Docker', 'Configurer le BIOS', 'Superviser le réseau'], answer: 0, explain: 'Kubectl : outil CLI de Kubernetes pour exécuter des commandes dans les clusters : déployer des applications, inspecter et gérer les ressources, consulter les logs…' },
  { id: 'vq1408', module: 'v14', q: 'Quel composant stocke la configuration et l\u2019état du cluster ?', options: ['Etcd : stockage distribué persistant et léger (configuration, état, événements)', 'API Server', 'Scheduler', 'Kubelet'], answer: 0, explain: 'Etcd : unité de stockage distribuée persistante et légère — la configuration, l\u2019état du cluster, les événements qui se produisent.' },
  { id: 'vq1409', module: 'v14', q: 'Quel est le rôle du Scheduler ?', options: ['Sélectionner quel Node devrait faire tourner un Pod, en récoltant en temps réel mémoire, disque, CPU des nœuds', 'Routage du trafic', 'Stocker les secrets', 'Créer les images'], answer: 0, explain: 'Scheduler : l\u2019ordonnanceur sélectionne quel Node devrait faire tourner un Pod (récolte en temps réel : occupation mémoire, capacité disque, taux CPU).' },
  { id: 'vq1410', module: 'v14', q: 'Quels contrôleurs s\u2019exécutent dans le Controller Manager ?', options: ['DaemonSet Controller et Replication Controller', 'Kubelet et Kube-proxy', 'etcd et API Server', 'Nginx et Apache'], answer: 0, explain: 'Controller Manager : processus dans lequel s\u2019exécutent les contrôleurs principaux de Kubernetes tels que DaemonSet Controller (service principal) et le Replication Controller.' },
  { id: 'vq1411', module: 'v14', q: 'Qu\u2019est-ce que le Kubelet ?', options: ['Responsable de l\u2019état d\u2019exécution du nœud : conteneurs en bonne santé, organisés en Pods sous la direction du plan de contrôle', 'Un proxy HTTP', 'Le stockage du cluster', 'L\u2019interface web'], answer: 0, explain: 'Kubelet : responsable de l\u2019état d\u2019exécution du nœud — assurer que tous les conteneurs sur un nœud sont en bonne santé, organisés en Pods sous la direction du plan de contrôle.' },
  { id: 'vq1412', module: 'v14', q: 'Que fait Kube-proxy ?', options: ['Route le trafic vers le conteneur approprié selon l\u2019adresse IP et le port de la requête entrante', 'Surveille le CPU', 'Sauvegarde l\u2019état', 'Compile les pods'], answer: 0, explain: 'Kube-proxy : responsable d\u2019effectuer le routage du trafic vers le conteneur approprié en se basant sur l\u2019adresse IP et le numéro de port de la requête entrante.' },
  { id: 'vq1413', module: 'v14', q: 'Que surveille cAdvisor ?', options: ['La consommation des ressources et performances (CPU, mémoire, disque, réseau) des conteneurs du Node', 'Les logs applicatifs', 'Les utilisateurs', 'Le DNS'], answer: 0, explain: 'cAdvisor : agent qui surveille et récupère les données de consommation des ressources et performances (processeur, mémoire, utilisation disque et réseau) des conteneurs du Node.' },
  { id: 'vq1414', module: 'v14', q: 'Les containers d\u2019un Pod partagent…', options: ['Le même Network, Namespace, IP et Ports ; ils communiquent via localhost ; ils partagent des shared volumes', 'Uniquement le disque', 'Rien du tout', 'Leur kernel séparé'], answer: 0, explain: 'Pod : groupe de containers déployés ensemble — toujours démarrés/arrêtés/répliqués EN GROUPE, mêmes Network/Namespace/IP/Ports, communication via localhost, shared volumes. Le Pod est l\u2019entité de base répliquée sur les nœuds.' },
  { id: 'vq1415', module: 'v14', q: 'Que permet un Volume Kubernetes ?', options: ['Espace de stockage attaché à un conteneur ou un groupe de conteneurs d\u2019un même Pod, persistant indépendamment du conteneur', 'Uniquement le stockage du BIOS', 'Rien, obsolète', 'Le stockage du DNS'], answer: 0, explain: 'Volume : espace de stockage pouvant être attaché à un conteneur ou à un groupe de conteneurs dans un même Pod ; peut persister indépendamment du conteneur (ex. partager un même répertoire dans un Pod).' },
  { id: 'vq1416', module: 'v14', q: 'Que décrit le fichier de Déploiement ?', options: ['L\u2019architecture cible : conteneurs du Pod, détails de réplication, stratégies de mise à jour — maintenue par le contrôleur', 'Uniquement l\u2019image Docker', 'Le réseau physique', 'Les utilisateurs'], answer: 0, explain: 'Déploiement = élément central : fichier décrivant l\u2019architecture cible (conteneurs, réplication, stratégies de maj) ; le déploiement du contrôleur MAINTIENT cet état (pod qui plante → désactivé, enlevé du LB, remplacé sur un autre nœud).' },
  { id: 'vq1417', module: 'v14', q: 'Dans l\u2019exemple myDeployment.yaml, combien de pods sont répliqués ?', options: ['3 (champ replicas)', '1', '5', '10'], answer: 0, explain: 'metadata: name: nginx ; spec: replicas: 3 → le déploiement crée trois pods répliqués, libellés app:nginx, exécutant nginx:1.7.9 avec containerPort: 80.' },
  { id: 'vq1418', module: 'v14', q: 'Quelle commande applique le fichier de déploiement du cours ?', options: ['$ kubectl create -f myDeployment.yaml', '$ kubectl run yaml', '$ kubectl apply image', '$ kubectl deploy nginx'], answer: 0, explain: '$ kubectl create -f myDeployment.yaml (create -f : créer à partir du fichier descripteur).' },
  { id: 'vq1419', module: 'v14', q: 'Quel Service type expose le service à l\u2019intérieur du cluster via une IP interne ?', options: ['ClusterIP (ex. BDD accessible uniquement par les autres apps du cluster)', 'NodePort', 'LoadBalancer', 'ExternalName'], answer: 0, explain: 'ClusterIP : expose le service à l\u2019intérieur du cluster via une adresse IP interne — ex. un service de BDD accessible uniquement par d\u2019autres applications du cluster.' },
  { id: 'vq1420', module: 'v14', q: 'Quel Service type pour une app web accessible depuis le réseau local via un port sur chaque nœud ?', options: ['NodePort', 'ClusterIP', 'LoadBalancer', 'Ingress'], answer: 0, explain: 'NodePort : expose le service via un port spécifique sur chaque nœud du cluster — ex. une application web simple accessible depuis votre réseau local.' },
  { id: 'vq1421', module: 'v14', q: 'Quel Service type pour une app de production publique derrière un LB externe ?', options: ['LoadBalancer', 'ClusterIP', 'NodePort', 'none'], answer: 0, explain: 'LoadBalancer : expose le service via un load balancer externe — ex. une application web en production accessible publiquement avec plusieurs pods derrière le LB.' },
  { id: 'vq1422', module: 'v14', q: 'Qu\u2019est-ce que Minikube ?', options: ['Un outil qui fait tourner un cluster Kubernetes à UN nœud unique dans une machine virtuelle sur votre machine (avec l\u2019essentiel de Docker et Kubernetes)', 'Un hyperviseur de type 1', 'Un registre d\u2019images', 'Un load balancer'], answer: 0, explain: 'Minikube : cluster Kubernetes à un nœud unique dans une VM sur votre machine — une VM avec l\u2019essentiel des packages de Docker et Kubernetes.' },
  { id: 'vq1423', module: 'v14', q: 'Quels hyperviseurs pour minikube sous Windows et Linux (cours) ?', options: ['Windows : VirtualBox, Hyper-V ; Linux : VirtualBox, KVM', 'Windows : KVM ; Linux : Hyper-V', 'macOS : Hyper-V', 'Aucun besoin d\u2019hyperviseur'], answer: 0, explain: 'Tableau du cours : macOS → VirtualBox, VMware Fusion, HyperKit ; Linux → VirtualBox, KVM ; Windows → VirtualBox, Hyper-V. Sans Hyper-V sous Windows : installer VirtualBox (vérifier avec systeminfo).' },
  { id: 'vq1424', module: 'v14', q: 'Quelle commande installe minikube et kubectl avec Chocolatey ?', options: ['> choco install minikube kubernetes-cli', '> apt install minikube', '> npm i minikube', '> docker install k8s'], answer: 0, explain: 'La façon la plus simple sur Windows : Chocolatey (droits administrateur) : choco install minikube kubernetes-cli — puis fermer la session CLI et redémarrer (ajouté au PATH).' },
  { id: 'vq1425', module: 'v14', q: 'Que télécharge `minikube start` ?', options: ['Une image de VM légère (Boot2Docker) contenant tous les outils docker et kubernetes, puis crée une config de démarrage et démarre le cluster', 'Windows 10', 'Uniquement kubectl', 'Une image ubuntu complète'], answer: 0, explain: 'minikube start télécharge une image de VM légère (Boot2Docker) avec tous les outils docker et kubernetes, crée une configuration de démarrage et démarre le cluster (sortie du cours : Preparing Kubernetes v1.15.2 on Docker 18.09.8 … Done! kubectl is now configured to use "minikube").' },
  { id: 'vq1426', module: 'v14', q: 'Que retourne `minikube docker-env` (cours) ?', options: ['Les variables pour connecter le client docker au daemon de Minikube : DOCKER_HOST=tcp://192.168.99.100:2376, DOCKER_TLS_VERIFY=1, DOCKER_CERT_PATH', 'Les pods actifs', 'L\u2019adresse du Dashboard', 'Le mot de passe root'], answer: 0, explain: 'minikube docker-env retourne les variables d\u2019environnement nécessaires pour utiliser le Docker daemon à l\u2019intérieur de Minikube : eval $(minikube docker-env) puis echo $DOCKER_HOST → tcp://192.168.99.100:2376.' },
  { id: 'vq1427', module: 'v14', q: 'Dans la démo, le Dockerfile de l\u2019app Node.js est :', options: ['FROM node:6.14.2 / EXPOSE 8080 / COPY server.js . / CMD node server.js', 'FROM ubuntu / RUN node', 'FROM nginx / COPY app.js', 'FROM alpine / CMD ping'], answer: 0, explain: 'Dockerfile : FROM node:6.14.2, EXPOSE 8080, COPY server.js ., CMD node server.js — avec server.js : serveur http sur 8080 répondant « Hello World! ».' },
  { id: 'vq1428', module: 'v14', q: 'Quelle commande construit l\u2019image de la démo ?', options: ['$ docker build . -t app-test:v1', '$ kubectl build app-test', '$ minikube image build', '$ docker push app-test'], answer: 0, explain: 'docker build . -t app-test:v1 → Step 1/4 … Successfully built / Successfully tagged app-test:v1.' },
  { id: 'vq1429', module: 'v14', q: 'Quelle commande déploie app-test dans un pod (cours) ?', options: ['$ kubectl create deployment app-test --image=app-test:v1', '$ kubectl run pod app-test', '$ minikube deploy app-test', '$ kubectl install app-test'], answer: 0, explain: 'kubectl create deployment app-test --image=app-test:v1 → deployment.apps/app-test created ; puis kubectl get deployments et kubectl get pods (app-test-5f78dcf7f8-2ts2w Running).' },
  { id: 'vq1430', module: 'v14', q: 'Quelle commande expose le port 8080 (cours) ?', options: ['$ kubectl expose deployment app-test --type=NodePort --port=8080', '$ kubectl open port 8080', '$ minikube expose 8080', '$ kubectl port forward'], answer: 0, explain: 'kubectl expose deployment app-test --type=NodePort --port=8080 → service/app-test exposed. describe service : Type NodePort, IP 10.108.16.123, Port 8080/TCP, NodePort 31708/TCP, Endpoints 172.17.0.11:8080.' },
  { id: 'vq1431', module: 'v14', q: 'Quelle URL donne `minikube service app-test` ?', options: ['http://192.168.99.100:31708', 'http://localhost:8080', 'https://app-test.io', 'http://10.108.16.123'], answer: 0, explain: 'minikube service app-test → URL http://192.168.99.100:31708, ouvre le navigateur : Hello World! (en local aussi : kubectl exec -ti … bash puis curl http://localhost:8080).' },
  { id: 'vq1432', module: 'v14', q: 'Quel est l\u2019ordre de nettoyage final du cours ?', options: ['kubectl delete service app-test → minikube stop → minikube delete', 'minikube delete → kubectl delete', 'Rien à nettoyer', 'docker rm -f $(docker ps -aq)'], answer: 0, explain: 'Nettoyage : kubectl delete service app-test (service "app-test" deleted) → minikube stop ("minikube" stopped) → minikube delete (The "minikube" cluster has been deleted).' },
]
